25	// Ping-pong state for chunked TBROADCAST transfers
26	struct TbroadcastPingPongState {
27	    bool usePing = true;
28	    bool hasPending = false;
29	    int64_t pendingDstOffset = 0;
30	    int pendingRows = 0;
31	    int pendingCols = 0;
32	};
33	
34	// TLOAD src chunk → sync → TSTORE to all ranks → sync
35	template <
36	    typename ParallelGroupType, typename TileData, typename SrcViewT, typename DstViewT, typename DynShapeT,
37	    typename DynStrideT>
38	PTO_INTERNAL void TbroadcastChunkTransfer(
39	    ParallelGroupType& parallelGroup, TileData& tile, SrcViewT& srcView, int64_t dstOffset, const DynShapeT& chunkShape,
40	    const DynStrideT& dstChunkStride, int nranks)
41	{
42	    TLOAD(tile, srcView);
43	    set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
44	    wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
45	    for (int r = 0; r < nranks; ++r) {
46	        DstViewT dstView(parallelGroup[r].data() + dstOffset, chunkShape, dstChunkStride);
47	        TSTORE(dstView, tile);
48	    }
49	    set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
50	    wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
51	}
52	
53	// Process one (dim0, dim1, dim2) slice with 2D row/col sliding for chunked broadcast
54	template <
55	    typename ParallelGroupType, typename TileData, typename SrcViewT, typename DstViewT, typename DynShape,
56	    typename GlobalSrcData, typename DynStride>
57	PTO_INTERNAL void TbroadcastChunked2DSlice(
58	    ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& stagingTileData, int64_t srcBase,
59	    int64_t dstOff, int gShape3, int gShape4, int tileValidRow, int tileValidCol, const int (&srcPitch)[5],
60	    const int (&dstPitch)[5], const DynStride& srcChunkStride, const DynStride& dstChunkStride, int nranks)
61	{
62	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
63	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
64	    for (int rowCursor = 0; rowCursor < gShape3; rowCursor += tileValidRow) {
65	        int curRows = (rowCursor + tileValidRow <= gShape3) ? tileValidRow : (gShape3 - rowCursor);
66	        if constexpr (isDynamicRow)
67	            stagingTileData.RowMaskInternal = curRows;
68	        for (int colCursor = 0; colCursor < gShape4; colCursor += tileValidCol) {
69	            int curCols = (colCursor + tileValidCol <= gShape4) ? tileValidCol : (gShape4 - colCursor);
70	            if constexpr (isDynamicCol)
71	                stagingTileData.ColMaskInternal = curCols;
72	            int64_t srcOff =
73	                srcBase + static_cast<int64_t>(rowCursor) * srcPitch[3] + static_cast<int64_t>(colCursor) * srcPitch[4];
74	            int64_t curDstOff =
75	                dstOff + static_cast<int64_t>(rowCursor) * dstPitch[3] + static_cast<int64_t>(colCursor) * dstPitch[4];
76	            DynShape chunkShape(1, 1, 1, curRows, curCols);
77	            SrcViewT srcView(srcGlobalData.data() + srcOff, chunkShape, srcChunkStride);
78	            TbroadcastChunkTransfer<ParallelGroupType, TileData, SrcViewT, DstViewT>(
79	                parallelGroup, stagingTileData, srcView, curDstOff, chunkShape, dstChunkStride, nranks);
80	        }
81	    }
82	}
