84	// 2D sliding chunked broadcast with single buffer
85	template <typename ParallelGroupType, typename GlobalSrcData, typename TileData>
86	PTO_INTERNAL void TbroadcastChunkedSingle(
87	    ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& stagingTileData, int gShape0, int gShape1,
88	    int gShape2, int gShape3, int gShape4, int tileValidRow, int tileValidCol, int nranks)
89	{
90	    using GlobalDstData = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
91	    using T = typename GlobalSrcData::RawDType;
92	    const int srcPitch[5] = {
93	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_0)),
94	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_1)),
95	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_2)),
96	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_3)),
97	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_4))};
98	    const int dstPitch[5] = {
99	        static_cast<int>(parallelGroup[0].GetStride(GlobalTensorDim::DIM_0)),
100	        static_cast<int>(parallelGroup[0].GetStride(GlobalTensorDim::DIM_1)),
101	        static_cast<int>(parallelGroup[0].GetStride(GlobalTensorDim::DIM_2)),
102	        static_cast<int>(parallelGroup[0].GetStride(GlobalTensorDim::DIM_3)),
103	        static_cast<int>(parallelGroup[0].GetStride(GlobalTensorDim::DIM_4))};
104	    using DynShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
105	    using DynStride = Stride<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
106	    using SrcViewT = GlobalTensor<T, DynShape, DynStride, GlobalSrcData::layout>;
107	    using DstViewT = GlobalTensor<T, DynShape, DynStride, GlobalDstData::layout>;
108	    DynStride srcChunkStride(srcPitch[0], srcPitch[1], srcPitch[2], srcPitch[3], srcPitch[4]);
109	    DynStride dstChunkStride(dstPitch[0], dstPitch[1], dstPitch[2], dstPitch[3], dstPitch[4]);
110	
111	    for (int dim0 = 0; dim0 < gShape0; ++dim0) {
112	        for (int dim1 = 0; dim1 < gShape1; ++dim1) {
113	            for (int dim2 = 0; dim2 < gShape2; ++dim2) {
114	                const int64_t srcBase = static_cast<int64_t>(dim0) * srcPitch[0] +
115	                                        static_cast<int64_t>(dim1) * srcPitch[1] +
116	                                        static_cast<int64_t>(dim2) * srcPitch[2];
117	                const int64_t dstBase = static_cast<int64_t>(dim0) * dstPitch[0] +
118	                                        static_cast<int64_t>(dim1) * dstPitch[1] +
119	                                        static_cast<int64_t>(dim2) * dstPitch[2];
120	                TbroadcastChunked2DSlice<ParallelGroupType, TileData, SrcViewT, DstViewT, DynShape>(
121	                    parallelGroup, srcGlobalData, stagingTileData, srcBase, dstBase, gShape3, gShape4, tileValidRow,
122	                    tileValidCol, srcPitch, dstPitch, srcChunkStride, dstChunkStride, nranks);
123	            }
124	        }
125	    }
126	}
