128	// Validate chunked constraints and dispatch to single-buffer chunked broadcast
129	template <typename ParallelGroupType, typename GlobalSrcData, typename TileData>
130	PTO_INTERNAL void TbroadcastChunkedSingleDispatch(
131	    ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& stagingTileData, int gShape0, int gShape1,
132	    int gShape2, int gShape3, int gShape4, int tileValidRow, int tileValidCol, int nranks)
133	{
134	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
135	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
136	    if constexpr (!isDynamicRow) {
137	        PTO_ASSERT(
138	            gShape3 % tileValidRow == 0,
139	            "TBROADCAST chunked: shape3 must be divisible by tile ValidRow when ValidRow is static. "
140	            "Use a Tile with DYNAMIC ValidRow for partial row chunk support.");
141	    }
142	    if constexpr (!isDynamicCol) {
143	        PTO_ASSERT(
144	            gShape4 % tileValidCol == 0,
145	            "TBROADCAST chunked: shape4 must be divisible by tile ValidCol when ValidCol is static. "
146	            "Use a Tile with DYNAMIC ValidCol for partial column chunk support.");
147	    }
148	
149	    TbroadcastChunkedSingle<ParallelGroupType, GlobalSrcData, TileData>(
150	        parallelGroup, srcGlobalData, stagingTileData, gShape0, gShape1, gShape2, gShape3, gShape4, tileValidRow,
151	        tileValidCol, nranks);
152	}
