154	// ============================================================================
155	// TBROADCAST_IMPL: Broadcast data from root NPU to all ranks
156	//
157	// The root loads srcGlobalData and stores it to every rank's buffer in the
158	// ParallelGroup.
159	//
160	// When the GlobalTensor exceeds the UB tile capacity in rows and/or columns,
161	// the transfer is automatically chunked via 2D sliding:
162	//   - Outer dimensions (DIM_0, DIM_1, DIM_2) are iterated explicitly.
163	//   - DIM_3 (rows) is split into tileValidRow-sized chunks.
164	//   - DIM_4 (cols) is split into tileValidCol-sized chunks.
165	//
166	// Constraints for chunked mode:
167	//   - If TileData has static ValidRow, shape3 must be divisible by ValidRow.
168	//   - If TileData has static ValidCol, shape4 must be divisible by ValidCol.
169	//   - All ranks in the ParallelGroup are assumed to have the same shape/strides.
170	// ============================================================================
171	
172	template <typename ParallelGroupType, typename GlobalSrcData, typename TileData>
173	PTO_INTERNAL void TBROADCAST_IMPL(
174	    ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& stagingTileData)
175	{
176	    using GlobalDstData = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
177	    using T = typename GlobalSrcData::RawDType;
178	
179	    static_assert(
180	        std::is_same_v<T, typename TileData::DType>,
181	        "TBROADCAST: TileData element type must match GlobalData element type");
182	    static_assert(
183	        std::is_same_v<T, typename GlobalDstData::RawDType>,
184	        "TBROADCAST: ParallelGroup element type must match source element type");
185	    static_assert(GlobalSrcData::layout == GlobalDstData::layout, "TBROADCAST: src/dst layout mismatch");
186	
187	    const int nranks = parallelGroup.GetSize();
188	    const int rootIdx = parallelGroup.GetRootIdx();
189	
190	    PTO_ASSERT(nranks > 0, "ParallelGroup size must be greater than 0!");
191	    PTO_ASSERT(rootIdx >= 0 && rootIdx < nranks, "rootIdx must be in range [0, nranks)!");
192	
193	    const int gShape0 = srcGlobalData.GetShape(GlobalTensorDim::DIM_0);
194	    const int gShape1 = srcGlobalData.GetShape(GlobalTensorDim::DIM_1);
195	    const int gShape2 = srcGlobalData.GetShape(GlobalTensorDim::DIM_2);
196	    const int gShape3 = srcGlobalData.GetShape(GlobalTensorDim::DIM_3);
197	    const int gShape4 = srcGlobalData.GetShape(GlobalTensorDim::DIM_4);
198	
199	    const int64_t totalRows = static_cast<int64_t>(gShape0) * gShape1 * gShape2 * gShape3;
200	    const int tileValidRow = stagingTileData.GetValidRow();
201	    const int tileValidCol = stagingTileData.GetValidCol();
202	
203	    PTO_ASSERT(tileValidRow > 0, "TBROADCAST: tileValidRow must be greater than 0");
204	    PTO_ASSERT(tileValidCol > 0, "TBROADCAST: tileValidCol must be greater than 0");
205	
206	    if (totalRows == 0 || gShape4 == 0) {
207	        return;
208	    }
209	
210	    if (nranks == 1) {
211	        TLOAD(stagingTileData, srcGlobalData);
212	        PtoSetWaitFlag<PIPE_MTE2, PIPE_MTE3>();
213	        TSTORE(parallelGroup[rootIdx], stagingTileData);
214	        PtoSetWaitFlag<PIPE_MTE3, PIPE_MTE2>();
215	        return;
216	    }
217	
218	    if (totalRows <= tileValidRow && gShape4 <= tileValidCol) {
219	        TLOAD(stagingTileData, srcGlobalData);
220	        PtoSetWaitFlag<PIPE_MTE2, PIPE_MTE3>();
221	        for (int r = 0; r < nranks; ++r) {
222	            TSTORE(parallelGroup[r], stagingTileData);
223	            PtoSetWaitFlag<PIPE_MTE3, PIPE_MTE2>();
224	        }
225	        return;
226	    }
227	
228	    TbroadcastChunkedSingleDispatch<ParallelGroupType, GlobalSrcData, TileData>(
229	        parallelGroup, srcGlobalData, stagingTileData, gShape0, gShape1, gShape2, gShape3, gShape4, tileValidRow,
230	        tileValidCol, nranks);
231	}
