233	// Process one chunk iteration with ping-pong for broadcast
234	template <typename ParallelGroupType, typename GlobalSrcData, typename TileData, typename DynStrideT>
235	PTO_INTERNAL void TbroadcastPingPongProcessChunk(
236	    ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile,
237	    int64_t srcOffset, int64_t dstOffset, int currentRows, int currentCols, const DynStrideT& srcChunkStride,
238	    const DynStrideT& dstChunkStride, int nranks, TbroadcastPingPongState& state)
239	{
240	    using DstGlobalT = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
241	    using ElemT = typename GlobalSrcData::RawDType;
242	    using ChunkShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
243	    using SrcChunkView = GlobalTensor<ElemT, ChunkShape, DynStrideT, GlobalSrcData::layout>;
244	    using DstChunkView = GlobalTensor<ElemT, ChunkShape, DynStrideT, DstGlobalT::layout>;
245	
246	    const bool currentIsPing = state.usePing;
247	    TileData& loadTile = currentIsPing ? pingTile : pongTile;
248	    event_t curEvent = currentIsPing ? EVENT_ID0 : EVENT_ID1;
249	
250	    constexpr bool hasDynRow = (TileData::ValidRow == DYNAMIC);
251	    constexpr bool hasDynCol = (TileData::ValidCol == DYNAMIC);
252	    if constexpr (hasDynRow)
253	        loadTile.RowMaskInternal = currentRows;
254	    if constexpr (hasDynCol)
255	        loadTile.ColMaskInternal = currentCols;
256	
257	    ChunkShape chunkShape(1, 1, 1, currentRows, currentCols);
258	    SrcChunkView srcView(srcGlobalData.data() + srcOffset, chunkShape, srcChunkStride);
259	
260	    if (state.hasPending) {
261	        TileData& storeTile = currentIsPing ? pongTile : pingTile;
262	        event_t prevEvent = currentIsPing ? EVENT_ID1 : EVENT_ID0;
263	
264	        wait_flag(PIPE_MTE2, PIPE_MTE3, prevEvent);
265	
266	        ChunkShape pendShape(1, 1, 1, state.pendingRows, state.pendingCols);
267	        for (int r = 0; r < nranks; ++r) {
268	            DstChunkView dstView(parallelGroup[r].data() + state.pendingDstOffset, pendShape, dstChunkStride);
269	            TSTORE(dstView, storeTile);
270	        }
271	        TLOAD(loadTile, srcView);
272	
273	        set_flag(PIPE_MTE3, PIPE_MTE2, prevEvent);
274	        set_flag(PIPE_MTE2, PIPE_MTE3, curEvent);
275	        wait_flag(PIPE_MTE3, PIPE_MTE2, prevEvent);
276	    } else {
277	        TLOAD(loadTile, srcView);
278	        set_flag(PIPE_MTE2, PIPE_MTE3, curEvent);
279	    }
280	
281	    state.usePing = !currentIsPing;
282	    state.hasPending = true;
283	    state.pendingDstOffset = dstOffset;
284	    state.pendingRows = currentRows;
285	    state.pendingCols = currentCols;
286	}
287	
288	// Drain last pending broadcast stores
289	template <typename ParallelGroupType, typename TileData, typename DynStrideT>
290	PTO_INTERNAL void TbroadcastPingPongEpilogue(
291	    ParallelGroupType& parallelGroup, TileData& pingTile, TileData& pongTile, const TbroadcastPingPongState& state,
292	    const DynStrideT& dstChunkStride, int nranks)
293	{
294	    using DstGlobalT = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
295	    using ElemT = typename DstGlobalT::RawDType;
296	    if (!state.hasPending)
297	        return;
298	    using ChunkShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
299	    using DstChunkView = GlobalTensor<ElemT, ChunkShape, DynStrideT, DstGlobalT::layout>;
300	
301	    const bool finalInPong = state.usePing;
302	    TileData& lastTile = finalInPong ? pongTile : pingTile;
303	    event_t lastEvent = finalInPong ? EVENT_ID1 : EVENT_ID0;
304	
305	    wait_flag(PIPE_MTE2, PIPE_MTE3, lastEvent);
306	    ChunkShape lastShape(1, 1, 1, state.pendingRows, state.pendingCols);
307	    for (int r = 0; r < nranks; ++r) {
308	        DstChunkView dstView(parallelGroup[r].data() + state.pendingDstOffset, lastShape, dstChunkStride);
309	        TSTORE(dstView, lastTile);
310	    }
311	    set_flag(PIPE_MTE3, PIPE_MTE2, lastEvent);
312	    wait_flag(PIPE_MTE3, PIPE_MTE2, lastEvent);
313	}
314	
315	// 2D sliding chunked broadcast with ping-pong double buffering
316	template <typename ParallelGroupType, typename GlobalSrcData, typename TileData>
317	PTO_INTERNAL void TbroadcastChunkedPingPong(
318	    ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile, int gShape0,
319	    int gShape1, int gShape2, int gShape3, int gShape4, int tileValidRow, int tileValidCol, int nranks)
320	{
321	    const int srcStep[5] = {
322	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_0)),
323	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_1)),
324	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_2)),
325	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_3)),
326	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_4))};
327	    auto& refDst = parallelGroup[0];
328	    const int dstStep[5] = {
329	        static_cast<int>(refDst.GetStride(GlobalTensorDim::DIM_0)),
330	        static_cast<int>(refDst.GetStride(GlobalTensorDim::DIM_1)),
331	        static_cast<int>(refDst.GetStride(GlobalTensorDim::DIM_2)),
332	        static_cast<int>(refDst.GetStride(GlobalTensorDim::DIM_3)),
333	        static_cast<int>(refDst.GetStride(GlobalTensorDim::DIM_4))};
334	
335	    using DynStride = Stride<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
336	    DynStride srcChunkStride(srcStep[0], srcStep[1], srcStep[2], srcStep[3], srcStep[4]);
337	    DynStride dstChunkStride(dstStep[0], dstStep[1], dstStep[2], dstStep[3], dstStep[4]);
338	    TbroadcastPingPongState state;
339	
340	    for (int i0 = 0; i0 < gShape0; ++i0) {
341	        for (int i1 = 0; i1 < gShape1; ++i1) {
342	            for (int i2 = 0; i2 < gShape2; ++i2) {
343	                const int64_t srcBase = static_cast<int64_t>(i0) * srcStep[0] + static_cast<int64_t>(i1) * srcStep[1] +
344	                                        static_cast<int64_t>(i2) * srcStep[2];
345	                const int64_t dstBase = static_cast<int64_t>(i0) * dstStep[0] + static_cast<int64_t>(i1) * dstStep[1] +
346	                                        static_cast<int64_t>(i2) * dstStep[2];
347	                int rowCursor = 0;
348	                while (rowCursor < gShape3) {
349	                    const int rowRemain = gShape3 - rowCursor;
350	                    const int curRows = (rowRemain < tileValidRow) ? rowRemain : tileValidRow;
351	                    int colCursor = 0;
352	                    while (colCursor < gShape4) {
353	                        const int colRemain = gShape4 - colCursor;
354	                        const int curCols = (colRemain < tileValidCol) ? colRemain : tileValidCol;
355	                        const int64_t srcOff = srcBase + static_cast<int64_t>(rowCursor) * srcStep[3] +
356	                                               static_cast<int64_t>(colCursor) * srcStep[4];
357	                        const int64_t dstOff = dstBase + static_cast<int64_t>(rowCursor) * dstStep[3] +
358	                                               static_cast<int64_t>(colCursor) * dstStep[4];
359	                        TbroadcastPingPongProcessChunk<ParallelGroupType, GlobalSrcData, TileData>(
360	                            parallelGroup, srcGlobalData, pingTile, pongTile, srcOff, dstOff, curRows, curCols,
361	                            srcChunkStride, dstChunkStride, nranks, state);
362	                        colCursor += tileValidCol;
363	                    }
364	                    rowCursor += tileValidRow;
365	                }
366	            }
367	        }
368	    }
369	
370	    TbroadcastPingPongEpilogue<ParallelGroupType, TileData>(
371	        parallelGroup, pingTile, pongTile, state, dstChunkStride, nranks);
372	}
373	
374	// Validate chunked constraints and dispatch to ping-pong chunked broadcast
375	template <typename ParallelGroupType, typename GlobalSrcData, typename TileData>
376	PTO_INTERNAL void TbroadcastChunkedPingPongDispatch(
377	    ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile,
378	    const int (&dims)[5], int tileValidRow, int tileValidCol, int nranks)
379	{
380	    constexpr bool hasDynRow = (TileData::ValidRow == DYNAMIC);
381	    constexpr bool hasDynCol = (TileData::ValidCol == DYNAMIC);
382	    if constexpr (!hasDynRow) {
383	        PTO_ASSERT(
384	            dims[3] % tileValidRow == 0,
385	            "TBROADCAST chunked: shape3 must be divisible by tile ValidRow when ValidRow is static. "
386	            "Use a Tile with DYNAMIC ValidRow for partial row chunk support.");
387	    }
388	    if constexpr (!hasDynCol) {
389	        PTO_ASSERT(
390	            dims[4] % tileValidCol == 0,
391	            "TBROADCAST chunked: shape4 must be divisible by tile ValidCol when ValidCol is static. "
392	            "Use a Tile with DYNAMIC ValidCol for partial column chunk support.");
393	    }
394	
395	    TbroadcastChunkedPingPong<ParallelGroupType, GlobalSrcData, TileData>(
396	        parallelGroup, srcGlobalData, pingTile, pongTile, dims[0], dims[1], dims[2], dims[3], dims[4], tileValidRow,
397	        tileValidCol, nranks);
398	}
