400	// ============================================================================
401	// TBROADCAST_IMPL (ping-pong): Broadcast with double buffering
402	//
403	// Uses two staging tiles (pingTile, pongTile) to overlap TLOAD of the next
404	// chunk (MTE2) with TSTORE of the current chunk to all ranks (MTE3).
405	//
406	// Timeline without ping-pong:
407	//   [TLOAD chunk0] -> [N×TSTORE chunk0] -> [TLOAD chunk1] -> [N×TSTORE chunk1] -> ...
408	//
409	// Timeline with ping-pong:
410	//   [TLOAD chunk0] -> [N×TSTORE chunk0 | TLOAD chunk1] -> [N×TSTORE chunk1 | TLOAD chunk2] -> ...
411	//
412	// Constraints: same as TBROADCAST_IMPL for chunked mode.
413	// ============================================================================
414	
415	template <typename ParallelGroupType, typename GlobalSrcData, typename TileData>
416	PTO_INTERNAL void TBROADCAST_IMPL(
417	    ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile)
418	{
419	    using DstGlobalT = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
420	    using ElemT = typename GlobalSrcData::RawDType;
421	
422	    static_assert(
423	        std::is_same_v<ElemT, typename TileData::DType>,
424	        "TBROADCAST: TileData element type must match GlobalData element type");
425	    static_assert(
426	        std::is_same_v<ElemT, typename DstGlobalT::RawDType>,
427	        "TBROADCAST: ParallelGroup element type must match source element type");
428	    static_assert(GlobalSrcData::layout == DstGlobalT::layout, "TBROADCAST: src/dst layout mismatch");
429	
430	    const int nranks = parallelGroup.GetSize();
431	    const int rootIdx = parallelGroup.GetRootIdx();
432	
433	    PTO_ASSERT(nranks > 0, "ParallelGroup size must be greater than 0!");
434	    PTO_ASSERT(rootIdx >= 0 && rootIdx < nranks, "rootIdx must be in range [0, nranks)!");
435	
436	    const int dims[5] = {
437	        static_cast<int>(srcGlobalData.GetShape(GlobalTensorDim::DIM_0)),
438	        static_cast<int>(srcGlobalData.GetShape(GlobalTensorDim::DIM_1)),
439	        static_cast<int>(srcGlobalData.GetShape(GlobalTensorDim::DIM_2)),
440	        static_cast<int>(srcGlobalData.GetShape(GlobalTensorDim::DIM_3)),
441	        static_cast<int>(srcGlobalData.GetShape(GlobalTensorDim::DIM_4))};
442	
443	    const int64_t totalRows = static_cast<int64_t>(dims[0]) * dims[1] * dims[2] * dims[3];
444	    const int tileValidRow = pingTile.GetValidRow();
445	    const int tileValidCol = pingTile.GetValidCol();
446	
447	    PTO_ASSERT(tileValidRow > 0, "TBROADCAST: tileValidRow must be greater than 0");
448	    PTO_ASSERT(tileValidCol > 0, "TBROADCAST: tileValidCol must be greater than 0");
449	
450	    if (totalRows == 0 || dims[4] == 0) {
451	        return;
452	    }
453	
454	    if (nranks == 1) {
455	        TLOAD(pingTile, srcGlobalData);
456	        PtoSetWaitFlag<PIPE_MTE2, PIPE_MTE3>();
457	        TSTORE(parallelGroup[rootIdx], pingTile);
458	        PtoSetWaitFlag<PIPE_MTE3, PIPE_MTE2>();
459	        return;
460	    }
461	
462	    if (totalRows <= tileValidRow && dims[4] <= tileValidCol) {
463	        TLOAD(pingTile, srcGlobalData);
464	        PtoSetWaitFlag<PIPE_MTE2, PIPE_MTE3>();
465	        for (int r = 0; r < nranks; ++r) {
466	            TSTORE(parallelGroup[r], pingTile);
467	            PtoSetWaitFlag<PIPE_MTE3, PIPE_MTE2>();
468	        }
469	        return;
470	    }
471	
472	    TbroadcastChunkedPingPongDispatch<ParallelGroupType, GlobalSrcData, TileData>(
473	        parallelGroup, srcGlobalData, pingTile, pongTile, dims, tileValidRow, tileValidCol, nranks);
474	}
475	
476	// CCU engine is only available on A5 hardware.  Stub mirrors the URMA branch
477	// in `a2a3/async/TPutAsync.hpp`: the template name must exist for the
478	// qualified template-id `::pto::comm::TBROADCAST_CCU_IMPL<engine>(...)` in
479	// pto_comm_inst.hpp to parse on A2/A3; the static_assert is dependent on the
480	// `engine` parameter and only fires if the overload is actually instantiated.
481	// `a5/TBroadCast.hpp` defines `PTO_COMM_A5_TBROADCAST_PROVIDED` before
482	// including this header so the stub is omitted on A5 builds, where the real
483	// `TBROADCAST_CCU_IMPL` overload lives.  Otherwise the generic `Args&&...`
484	// pack would compete with the real `T&` parameters in `pto::comm`'s overload
485	// set and could win under partial ordering on some compilers.
486	#ifndef PTO_COMM_A5_TBROADCAST_PROVIDED
487	template <CollEngine engine = CollEngine::CCU, typename... Args>
488	PTO_INTERNAL void TBROADCAST_CCU_IMPL(Args&&...)
489	{
490	    static_assert(
491	        engine != CollEngine::CCU, "TBROADCAST<CollEngine::CCU> requires A5 hardware; "
492	                                   "CCU engine is not available on A2/A3.");
493	}
494	#endif // PTO_COMM_A5_TBROADCAST_PROVIDED
495	
496	} // namespace comm
497	} // namespace pto
498	
499	#endif // PTO_COMM_TBROADCAST_HPP
