34	// Simple gather path: per-rank data fits in a single tile, loop over all ranks
35	template <typename ParallelGroupType, typename GlobalDstData, typename TileData>
36	PTO_INTERNAL void TgatherSimple(
37	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& stagingTileData, int gShape0, int gShape1,
38	    int gShape2, int gShape3, int gShape4, int nranks, int perRankRows)
39	{
40	    using GlobalSrcData = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
41	    using T = typename GlobalSrcData::RawDType;
42	    const int dstStride3 = dstGlobalData.GetStride(GlobalTensorDim::DIM_3);
43	
44	    using DynShape5D = Shape<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
45	    using DynStride = Stride<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
46	    using DstViewT = GlobalTensor<T, DynShape5D, DynStride, GlobalDstData::layout>;
47	
48	    DynShape5D perRankShape(gShape0, gShape1, gShape2, gShape3, gShape4);
49	    DynStride dstViewStride(
50	        dstGlobalData.GetStride(GlobalTensorDim::DIM_0), dstGlobalData.GetStride(GlobalTensorDim::DIM_1),
51	        dstGlobalData.GetStride(GlobalTensorDim::DIM_2), dstStride3, dstGlobalData.GetStride(GlobalTensorDim::DIM_4));
52	
53	    for (int r = 0; r < nranks; ++r) {
54	        TLOAD(stagingTileData, parallelGroup[r]);
55	        set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
56	        wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
57	        int64_t dstOffset = static_cast<int64_t>(r) * perRankRows * dstStride3;
58	        DstViewT dstView(dstGlobalData.data() + dstOffset, perRankShape, dstViewStride);
59	        TSTORE(dstView, stagingTileData);
60	        set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
61	        wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
62	    }
63	}
64	
65	// Inner row/col 2D sliding loop for chunked gather
66	template <typename TileData, typename T, Layout srcLayout, Layout dstLayout>
67	PTO_INTERNAL void TgatherChunkedRowColLoop(
68	    TileData& stagingTileData, __gm__ T* srcPtr, __gm__ T* dstPtr, int64_t srcBase, int64_t dstBase, int gShape3,
69	    int gShape4, int tileValidRow, int tileValidCol, const int (&srcStep)[5], const int (&dstStep)[5])
70	{
71	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
72	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
73	    using ChunkShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
74	    using DynStride = Stride<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
75	    using SrcChunkView = GlobalTensor<T, ChunkShape, DynStride, srcLayout>;
76	    using DstChunkView = GlobalTensor<T, ChunkShape, DynStride, dstLayout>;
77	    DynStride srcChunkStride(srcStep[0], srcStep[1], srcStep[2], srcStep[3], srcStep[4]);
78	    DynStride dstChunkStride(dstStep[0], dstStep[1], dstStep[2], dstStep[3], dstStep[4]);
79	
80	    for (int rowOff = 0; rowOff < gShape3; rowOff += tileValidRow) {
81	        int curRows = (gShape3 - rowOff < tileValidRow) ? (gShape3 - rowOff) : tileValidRow;
82	        if constexpr (isDynamicRow)
83	            stagingTileData.RowMaskInternal = curRows;
84	        for (int colOff = 0; colOff < gShape4; colOff += tileValidCol) {
85	            int curCols = (gShape4 - colOff < tileValidCol) ? (gShape4 - colOff) : tileValidCol;
86	            if constexpr (isDynamicCol)
87	                stagingTileData.ColMaskInternal = curCols;
88	            const int64_t srcOff =
89	                srcBase + static_cast<int64_t>(rowOff) * srcStep[3] + static_cast<int64_t>(colOff) * srcStep[4];
90	            const int64_t dstOff =
91	                dstBase + static_cast<int64_t>(rowOff) * dstStep[3] + static_cast<int64_t>(colOff) * dstStep[4];
92	            ChunkShape chunkShape(1, 1, 1, curRows, curCols);
93	            SrcChunkView srcView(srcPtr + srcOff, chunkShape, srcChunkStride);
94	            TLOAD(stagingTileData, srcView);
95	            set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
96	            wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
97	            DstChunkView dstChunk(dstPtr + dstOff, chunkShape, dstChunkStride);
98	            TSTORE(dstChunk, stagingTileData);
99	            set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
100	            wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
101	        }
102	    }
103	}
104	
105	// 2D sliding chunked gather with single buffer
106	template <typename ParallelGroupType, typename GlobalDstData, typename TileData>
107	PTO_INTERNAL void TgatherChunkedSingle(
108	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& stagingTileData, int gShape0, int gShape1,
109	    int gShape2, int gShape3, int gShape4, int tileValidRow, int tileValidCol, int nranks, int perRankRows)
110	{
111	    using GlobalSrcData = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
112	    using T = typename GlobalSrcData::RawDType;
113	
114	    auto& refSrc = parallelGroup[0];
115	    const int srcStep[5] = {
116	        static_cast<int>(refSrc.GetStride(GlobalTensorDim::DIM_0)),
117	        static_cast<int>(refSrc.GetStride(GlobalTensorDim::DIM_1)),
118	        static_cast<int>(refSrc.GetStride(GlobalTensorDim::DIM_2)),
119	        static_cast<int>(refSrc.GetStride(GlobalTensorDim::DIM_3)),
120	        static_cast<int>(refSrc.GetStride(GlobalTensorDim::DIM_4))};
121	    const int dstStep[5] = {
122	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_0)),
123	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_1)),
124	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_2)),
125	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_3)),
126	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_4))};
127	
128	    for (int r = 0; r < nranks; ++r) {
129	        const int64_t rankDstBase = static_cast<int64_t>(r) * perRankRows * dstStep[3];
130	        for (int i0 = 0; i0 < gShape0; ++i0) {
131	            for (int i1 = 0; i1 < gShape1; ++i1) {
132	                for (int i2 = 0; i2 < gShape2; ++i2) {
133	                    const int64_t srcBase = static_cast<int64_t>(i0) * srcStep[0] +
134	                                            static_cast<int64_t>(i1) * srcStep[1] +
135	                                            static_cast<int64_t>(i2) * srcStep[2];
136	                    const int64_t dstBase = rankDstBase + static_cast<int64_t>(i0) * dstStep[0] +
137	                                            static_cast<int64_t>(i1) * dstStep[1] +
138	                                            static_cast<int64_t>(i2) * dstStep[2];
139	                    TgatherChunkedRowColLoop<TileData, T, GlobalSrcData::layout, GlobalDstData::layout>(
140	                        stagingTileData, parallelGroup[r].data(), dstGlobalData.data(), srcBase, dstBase, gShape3,
141	                        gShape4, tileValidRow, tileValidCol, srcStep, dstStep);
142	                }
143	            }
144	        }
145	    }
146	}
