148	// ============================================================================
149	// TGATHER_IMPL: Gather operation - root collects data from all ranks
150	//
151	// The calling NPU is the root and gathers data from all ranks, concatenating
152	// the results along DIM_3 (row dimension) into a local output buffer.
153	//
154	// Each rank r contributes data of shape (D0, D1, D2, H, W). The destination
155	// tensor has shape (D0, D1, D2, N*H, W), where rank r's data is placed at
156	// rows [r*H, (r+1)*H).
157	//
158	// When the per-rank GlobalTensor exceeds the UB tile capacity in rows and/or
159	// columns, the transfer is automatically chunked via 2D sliding:
160	//   - Outer dimensions (DIM_0, DIM_1, DIM_2) are iterated explicitly.
161	//   - DIM_3 (rows) is split into tileValidRow-sized chunks.
162	//   - DIM_4 (cols) is split into tileValidCol-sized chunks.
163	//
164	// Constraints for chunked mode:
165	//   - If TileData has static ValidRow, per-rank DIM_3 must be divisible by ValidRow.
166	//   - If TileData has static ValidCol, DIM_4 must be divisible by ValidCol.
167	//   - All source tensors in the ParallelGroup are assumed to have the same shape/strides.
168	// ============================================================================
169	
170	template <typename ParallelGroupType, typename GlobalDstData, typename TileData>
171	PTO_INTERNAL void TGATHER_IMPL(
172	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& stagingTileData)
173	{
174	    using GlobalSrcData = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
175	    using T = typename GlobalSrcData::RawDType;
176	
177	    static_assert(std::is_same_v<T, typename GlobalDstData::RawDType>, "TGATHER: GlobalData type mismatch!");
178	    static_assert(
179	        std::is_same_v<T, typename TileData::DType>,
180	        "TGATHER: TileData element type must match GlobalData element type");
181	    static_assert(GlobalSrcData::layout == GlobalDstData::layout, "TGATHER: src/dst layout mismatch");
182	
183	    const int nranks = parallelGroup.GetSize();
184	    PTO_ASSERT(nranks > 0, "TGATHER: ParallelGroup size must be positive");
185	    const int rootIdx = parallelGroup.GetRootIdx();
186	    PTO_ASSERT(rootIdx >= 0 && rootIdx < nranks, "TGATHER: rootIdx out of range");
187	
188	    auto& srcRef = parallelGroup[0];
189	    const int gShape0 = srcRef.GetShape(GlobalTensorDim::DIM_0);
190	    const int gShape1 = srcRef.GetShape(GlobalTensorDim::DIM_1);
191	    const int gShape2 = srcRef.GetShape(GlobalTensorDim::DIM_2);
192	    const int gShape3 = srcRef.GetShape(GlobalTensorDim::DIM_3);
193	    const int gShape4 = srcRef.GetShape(GlobalTensorDim::DIM_4);
194	
195	    const int perRankRows = gShape3;
196	    const int tileValidRow = stagingTileData.GetValidRow();
197	    const int tileValidCol = stagingTileData.GetValidCol();
198	    const int64_t totalRows = static_cast<int64_t>(gShape0) * gShape1 * gShape2 * gShape3;
199	
200	    PTO_ASSERT(tileValidRow > 0, "TGATHER: tileValidRow must be greater than 0");
201	    PTO_ASSERT(tileValidCol > 0, "TGATHER: tileValidCol must be greater than 0");
202	
203	    if (totalRows == 0 || gShape4 == 0) {
204	        return;
205	    }
206	
207	    // Simple path: per-rank data fits in UB tile
208	    if (totalRows <= tileValidRow && gShape4 <= tileValidCol) {
209	        TgatherSimple<ParallelGroupType, GlobalDstData, TileData>(
210	            parallelGroup, dstGlobalData, stagingTileData, gShape0, gShape1, gShape2, gShape3, gShape4, nranks,
211	            perRankRows);
212	        return;
213	    }
214	
215	    // 2D sliding chunked path
216	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
217	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
218	
219	    if constexpr (!isDynamicRow) {
220	        PTO_ASSERT(
221	            gShape3 % tileValidRow == 0,
222	            "TGATHER chunked: per-rank DIM_3 must be divisible by tile ValidRow when static. "
223	            "Use a Tile with DYNAMIC ValidRow for partial row chunk support.");
224	    }
225	    if constexpr (!isDynamicCol) {
226	        PTO_ASSERT(
227	            gShape4 % tileValidCol == 0, "TGATHER chunked: DIM_4 must be divisible by tile ValidCol when static. "
228	                                         "Use a Tile with DYNAMIC ValidCol for partial column chunk support.");
229	    }
230	
231	    TgatherChunkedSingle<ParallelGroupType, GlobalDstData, TileData>(
232	        parallelGroup, dstGlobalData, stagingTileData, gShape0, gShape1, gShape2, gShape3, gShape4, tileValidRow,
233	        tileValidCol, nranks, perRankRows);
234	}
235	
236	// Process one chunk iteration with ping-pong double buffering for gather
237	template <typename ParallelGroupType, typename GlobalDstData, typename TileData, typename DynStrideT>
238	PTO_INTERNAL void TgatherPingPongProcessChunk(
239	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& pingTile, TileData& pongTile,
240	    int64_t srcOffset, int64_t dstOffset, int currentRows, int currentCols, const DynStrideT& srcChunkStride,
241	    const DynStrideT& dstChunkStride, int rank, TgatherPingPongState& state)
242	{
243	    using SrcGlobalT = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
244	    using ElemT = typename SrcGlobalT::RawDType;
245	    using ChunkShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
246	    using SrcChunkView = GlobalTensor<ElemT, ChunkShape, DynStrideT, SrcGlobalT::layout>;
247	    using DstChunkView = GlobalTensor<ElemT, ChunkShape, DynStrideT, GlobalDstData::layout>;
248	
249	    const bool currentIsPing = state.usePing;
250	    constexpr bool hasDynRow = (TileData::ValidRow == DYNAMIC);
251	    constexpr bool hasDynCol = (TileData::ValidCol == DYNAMIC);
252	
253	    TileData& loadTile = currentIsPing ? pingTile : pongTile;
254	    event_t curEvent = currentIsPing ? EVENT_ID0 : EVENT_ID1;
255	
256	    if constexpr (hasDynRow)
257	        loadTile.RowMaskInternal = currentRows;
258	    if constexpr (hasDynCol)
259	        loadTile.ColMaskInternal = currentCols;
260	
261	    ChunkShape chunkShape(1, 1, 1, currentRows, currentCols);
262	    SrcChunkView srcView(parallelGroup[rank].data() + srcOffset, chunkShape, srcChunkStride);
263	
264	    if (state.hasPending) {
265	        TileData& storeTile = currentIsPing ? pongTile : pingTile;
266	        event_t prevEvent = currentIsPing ? EVENT_ID1 : EVENT_ID0;
267	
268	        wait_flag(PIPE_MTE2, PIPE_MTE3, prevEvent);
269	
270	        ChunkShape pendShape(1, 1, 1, state.pendingRows, state.pendingCols);
271	        DstChunkView pendDst(dstGlobalData.data() + state.pendingDstOffset, pendShape, dstChunkStride);
272	
273	        TSTORE(pendDst, storeTile);
274	        TLOAD(loadTile, srcView);
275	
276	        set_flag(PIPE_MTE3, PIPE_MTE2, prevEvent);
277	        set_flag(PIPE_MTE2, PIPE_MTE3, curEvent);
278	
279	        wait_flag(PIPE_MTE3, PIPE_MTE2, prevEvent);
280	    } else {
281	        TLOAD(loadTile, srcView);
282	        set_flag(PIPE_MTE2, PIPE_MTE3, curEvent);
283	    }
284	
285	    state.pendingDstOffset = dstOffset;
286	    state.pendingRows = currentRows;
287	    state.pendingCols = currentCols;
288	    state.hasPending = true;
289	    state.usePing = !currentIsPing;
290	}
291	
292	// Drain the last pending TSTORE after the chunked ping-pong loop completes
293	template <typename GlobalDstData, typename TileData, typename DynStrideT>
294	PTO_INTERNAL void TgatherPingPongEpilogue(
295	    GlobalDstData& dstGlobalData, TileData& pingTile, TileData& pongTile, const TgatherPingPongState& state,
296	    const DynStrideT& dstChunkStride)
297	{
298	    if (!state.hasPending)
299	        return;
300	    using ElemT = typename GlobalDstData::RawDType;
301	    using ChunkShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
302	    using DstChunkView = GlobalTensor<ElemT, ChunkShape, DynStrideT, GlobalDstData::layout>;
303	
304	    const bool finalInPong = state.usePing;
305	    TileData& lastTile = finalInPong ? pongTile : pingTile;
306	    event_t lastEvent = finalInPong ? EVENT_ID1 : EVENT_ID0;
307	
308	    wait_flag(PIPE_MTE2, PIPE_MTE3, lastEvent);
309	    ChunkShape lastShape(1, 1, 1, state.pendingRows, state.pendingCols);
310	    DstChunkView dstView(dstGlobalData.data() + state.pendingDstOffset, lastShape, dstChunkStride);
311	    TSTORE(dstView, lastTile);
312	    set_flag(PIPE_MTE3, PIPE_MTE2, lastEvent);
313	    wait_flag(PIPE_MTE3, PIPE_MTE2, lastEvent);
314	}
315	
316	// Process one (rank, dim0, dim1, dim2) slice with 2D row/col sliding for chunked gather ping-pong
317	template <typename ParallelGroupType, typename GlobalDstData, typename TileData, typename DynStride>
318	PTO_INTERNAL void TgatherPingPong2DSlice(
319	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& pingTile, TileData& pongTile,
320	    int64_t srcBase, int64_t dstBase, int gShape3, int gShape4, int tileValidRow, int tileValidCol,
321	    const int (&srcPitch)[5], const int (&dstPitch)[5], const DynStride& srcChunkStride,
322	    const DynStride& dstChunkStride, int rank, TgatherPingPongState& state)
323	{
324	    int rowCursor = 0;
325	    while (rowCursor < gShape3) {
326	        const int curRows = (gShape3 - rowCursor < tileValidRow) ? (gShape3 - rowCursor) : tileValidRow;
327	        int colCursor = 0;
328	        while (colCursor < gShape4) {
329	            const int curCols = (gShape4 - colCursor < tileValidCol) ? (gShape4 - colCursor) : tileValidCol;
330	            const int64_t srcOff =
331	                srcBase + static_cast<int64_t>(rowCursor) * srcPitch[3] + static_cast<int64_t>(colCursor) * srcPitch[4];
332	            const int64_t dstOff =
333	                dstBase + static_cast<int64_t>(rowCursor) * dstPitch[3] + static_cast<int64_t>(colCursor) * dstPitch[4];
334	            TgatherPingPongProcessChunk<ParallelGroupType, GlobalDstData, TileData>(
335	                parallelGroup, dstGlobalData, pingTile, pongTile, srcOff, dstOff, curRows, curCols, srcChunkStride,
336	                dstChunkStride, rank, state);
337	            colCursor += tileValidCol;
338	        }
339	        rowCursor += tileValidRow;
340	    }
341	}
342	
343	// 2D sliding chunked gather with ping-pong double buffering
344	template <typename ParallelGroupType, typename GlobalDstData, typename TileData>
345	PTO_INTERNAL void TgatherChunkedPingPong(
346	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& pingTile, TileData& pongTile, int gShape0,
347	    int gShape1, int gShape2, int gShape3, int gShape4, int tileValidRow, int tileValidCol, int nranks, int perRankRows)
348	{
349	    auto& refSrc = parallelGroup[0];
350	    const int srcPitch[5] = {
351	        static_cast<int>(refSrc.GetStride(GlobalTensorDim::DIM_0)),
352	        static_cast<int>(refSrc.GetStride(GlobalTensorDim::DIM_1)),
353	        static_cast<int>(refSrc.GetStride(GlobalTensorDim::DIM_2)),
354	        static_cast<int>(refSrc.GetStride(GlobalTensorDim::DIM_3)),
355	        static_cast<int>(refSrc.GetStride(GlobalTensorDim::DIM_4))};
356	    const int dstPitch[5] = {
357	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_0)),
358	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_1)),
359	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_2)),
360	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_3)),
361	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_4))};
362	    using DynStride = Stride<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
363	    DynStride srcChunkStride(srcPitch[0], srcPitch[1], srcPitch[2], srcPitch[3], srcPitch[4]);
364	    DynStride dstChunkStride(dstPitch[0], dstPitch[1], dstPitch[2], dstPitch[3], dstPitch[4]);
365	    TgatherPingPongState state;
366	
367	    for (int r = 0; r < nranks; ++r) {
368	        const int64_t rankDstBase = static_cast<int64_t>(r) * perRankRows * dstPitch[3];
369	        for (int i0 = 0; i0 < gShape0; ++i0) {
370	            for (int i1 = 0; i1 < gShape1; ++i1) {
371	                for (int i2 = 0; i2 < gShape2; ++i2) {
372	                    const int64_t srcBase = static_cast<int64_t>(i0) * srcPitch[0] +
373	                                            static_cast<int64_t>(i1) * srcPitch[1] +
374	                                            static_cast<int64_t>(i2) * srcPitch[2];
375	                    const int64_t dstBase = rankDstBase + static_cast<int64_t>(i0) * dstPitch[0] +
376	                                            static_cast<int64_t>(i1) * dstPitch[1] +
377	                                            static_cast<int64_t>(i2) * dstPitch[2];
378	                    TgatherPingPong2DSlice<ParallelGroupType, GlobalDstData, TileData>(
379	                        parallelGroup, dstGlobalData, pingTile, pongTile, srcBase, dstBase, gShape3, gShape4,
380	                        tileValidRow, tileValidCol, srcPitch, dstPitch, srcChunkStride, dstChunkStride, r, state);
381	                }
382	            }
383	        }
384	    }
385	    TgatherPingPongEpilogue<GlobalDstData, TileData>(dstGlobalData, pingTile, pongTile, state, dstChunkStride);
386	}
387	
388	// ============================================================================
389	// TGATHER_IMPL (ping-pong): Gather with double buffering
390	//
391	// Uses two staging tiles (pingTile, pongTile) to overlap TLOAD of the next
392	// chunk (MTE2) with TSTORE of the current chunk (MTE3).
393	//
394	// Timeline without ping-pong:
395	//   [TLOAD chunk0] -> [TSTORE chunk0] -> [TLOAD chunk1] -> [TSTORE chunk1] -> ...
396	//
397	// Timeline with ping-pong:
398	//   [TLOAD chunk0] -> [TSTORE chunk0 | TLOAD chunk1] -> [TSTORE chunk1 | TLOAD chunk2] -> ...
399	//
400	// Constraints: same as TGATHER_IMPL for chunked mode.
401	// ============================================================================
402	
403	template <typename ParallelGroupType, typename GlobalDstData, typename TileData>
404	PTO_INTERNAL void TGATHER_IMPL(
405	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& pingTile, TileData& pongTile)
406	{
407	    using SrcGlobalT = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
408	    using ElemT = typename SrcGlobalT::RawDType;
409	
410	    static_assert(std::is_same_v<ElemT, typename GlobalDstData::RawDType>, "TGATHER: GlobalData type mismatch!");
411	    static_assert(
412	        std::is_same_v<ElemT, typename TileData::DType>,
413	        "TGATHER: TileData element type must match GlobalData element type");
414	    static_assert(SrcGlobalT::layout == GlobalDstData::layout, "TGATHER: src/dst layout mismatch");
415	
416	    const int nranks = parallelGroup.GetSize();
417	    const int rootIdx = parallelGroup.GetRootIdx();
418	
419	    PTO_ASSERT(nranks > 0, "ParallelGroup size must be greater than 0!");
420	    PTO_ASSERT(rootIdx >= 0 && rootIdx < nranks, "rootIdx must be in range [0, nranks)!");
421	
422	    auto& refTensor = parallelGroup[0];
423	    const int dims[5] = {
424	        static_cast<int>(refTensor.GetShape(GlobalTensorDim::DIM_0)),
425	        static_cast<int>(refTensor.GetShape(GlobalTensorDim::DIM_1)),
426	        static_cast<int>(refTensor.GetShape(GlobalTensorDim::DIM_2)),
427	        static_cast<int>(refTensor.GetShape(GlobalTensorDim::DIM_3)),
428	        static_cast<int>(refTensor.GetShape(GlobalTensorDim::DIM_4))};
429	
430	    const int perRankRows = dims[3];
431	    const int64_t totalRows = static_cast<int64_t>(dims[0]) * dims[1] * dims[2] * dims[3];
432	    const int tileValidRow = pingTile.GetValidRow();
433	    const int tileValidCol = pingTile.GetValidCol();
434	
435	    PTO_ASSERT(tileValidRow > 0, "TGATHER: tileValidRow must be greater than 0");
436	    PTO_ASSERT(tileValidCol > 0, "TGATHER: tileValidCol must be greater than 0");
437	
438	    if (totalRows == 0 || dims[4] == 0) {
439	        return;
440	    }
441	
442	    // Simple path: per-rank data fits in UB tile, no ping-pong benefit
443	    if (totalRows <= tileValidRow && dims[4] <= tileValidCol) {
444	        TgatherSimple<ParallelGroupType, GlobalDstData, TileData>(
445	            parallelGroup, dstGlobalData, pingTile, dims[0], dims[1], dims[2], dims[3], dims[4], nranks, perRankRows);
446	        return;
447	    }
448	
449	    // 2D sliding chunked path with ping-pong double buffering
450	    constexpr bool hasDynRow = (TileData::ValidRow == DYNAMIC);
451	    constexpr bool hasDynCol = (TileData::ValidCol == DYNAMIC);
452	
453	    if constexpr (!hasDynRow) {
454	        PTO_ASSERT(
455	            dims[3] % tileValidRow == 0,
456	            "TGATHER chunked: per-rank DIM_3 must be divisible by tile ValidRow when static.");
457	    }
458	    if constexpr (!hasDynCol) {
459	        PTO_ASSERT(
460	            dims[4] % tileValidCol == 0, "TGATHER chunked: DIM_4 must be divisible by tile ValidCol when static.");
461	    }
462	
463	    TgatherChunkedPingPong<ParallelGroupType, GlobalDstData, TileData>(
464	        parallelGroup, dstGlobalData, pingTile, pongTile, dims[0], dims[1], dims[2], dims[3], dims[4], tileValidRow,
465	        tileValidCol, nranks, perRankRows);
466	}
467	
468	// CCU engine is only available on A5 hardware.  This stub mirrors the
469	// `a2a3/async/TPutAsync.hpp` URMA branch: the name must exist as a template
470	// in `pto::comm` so that `::pto::comm::TGATHER_CCU_IMPL<engine>(...)` in
471	// pto_comm_inst.hpp parses on A2/A3 builds; the body's static_assert depends
472	// on the `engine` template parameter and only fires if the overload is
473	// actually instantiated, which is the misuse it flags.
474	// `a5/TGather.hpp` defines `PTO_COMM_A5_TGATHER_PROVIDED` before including
475	// this header so the stub is omitted on A5 builds, where the real
476	// `TGATHER_CCU_IMPL` overload lives.  Otherwise the generic `Args&&...` pack
477	// would compete with the real `T&` parameters in `pto::comm`'s overload set
478	// and could win under partial ordering on some compilers.
479	#ifndef PTO_COMM_A5_TGATHER_PROVIDED
480	template <CollEngine engine = CollEngine::CCU, typename... Args>
481	PTO_INTERNAL void TGATHER_CCU_IMPL(Args&&...)
482	{
483	    static_assert(
484	        engine != CollEngine::CCU, "TGATHER<CollEngine::CCU> requires A5 hardware; "
485	                                   "CCU engine is not available on A2/A3.");
486	}
487	#endif // PTO_COMM_A5_TGATHER_PROVIDED
488	
489	} // namespace comm
490	} // namespace pto
491	
492	#endif // PTO_COMM_TGATHER_HPP
