27	template <typename TileData>
28	PTO_INTERNAL void ReduceTiles(TileData& acc, TileData& recv, ReduceOp op)
29	{
30	    switch (op) {
31	        case ReduceOp::Sum:
32	            TADD(acc, acc, recv);
33	            break;
34	        case ReduceOp::Max:
35	            TMAX(acc, acc, recv);
36	            break;
37	        case ReduceOp::Min:
38	            TMIN(acc, acc, recv);
39	            break;
40	        default:
41	            PTO_ASSERT(false, "TREDUCE: unknown ReduceOp");
42	            break;
43	    }
