53	// Simple reduce path: entire data fits in one tile
54	template <typename ParallelGroupType, typename GlobalDstData, typename TileData>
55	PTO_INTERNAL void TreduceSimple(
56	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& accTileData, TileData& recvTileData,
57	    ReduceOp op, int rootIdx, int nranks)
58	{
59	    if (nranks == 1) {
60	        TLOAD(accTileData, parallelGroup[rootIdx]);
61	        set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
62	        wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
63	        TSTORE(dstGlobalData, accTileData);
64	        set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
65	        wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
66	        return;
67	    }
68	
69	    TLOAD(accTileData, parallelGroup[rootIdx]);
70	    set_flag(PIPE_MTE2, PIPE_V, EVENT_ID0);
71	    wait_flag(PIPE_MTE2, PIPE_V, EVENT_ID0);
72	
73	    for (int r = 0; r < nranks; ++r) {
74	        if (r == rootIdx)
75	            continue;
76	        TLOAD(recvTileData, parallelGroup[r]);
77	        set_flag(PIPE_MTE2, PIPE_V, EVENT_ID1);
78	        wait_flag(PIPE_MTE2, PIPE_V, EVENT_ID1);
79	        detail::ReduceTiles(accTileData, recvTileData, op);
80	        set_flag(PIPE_V, PIPE_MTE2, EVENT_ID0);
81	        wait_flag(PIPE_V, PIPE_MTE2, EVENT_ID0);
82	    }
83	
84	    set_flag(PIPE_V, PIPE_MTE3, EVENT_ID0);
85	    wait_flag(PIPE_V, PIPE_MTE3, EVENT_ID0);
86	    TSTORE(dstGlobalData, accTileData);
87	    set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
88	    wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
89	}
90	
91	// Process one chunk's full reduce pipeline (single buffer):
92	// TLOAD root → reduce all remote ranks → TSTORE result
93	template <typename ParallelGroupType, typename GlobalDstData, typename TileData, typename DynStrideT>
94	PTO_INTERNAL void TreduceProcessChunkSingle(
95	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& accTileData, TileData& recvTileData,
96	    ReduceOp op, int64_t srcOffset, int64_t dstOffset, int currentRows, int currentCols,
97	    const DynStrideT& srcChunkStride, const DynStrideT& dstChunkStride, int rootIdx, int nranks)
98	{
99	    using GlobalSrcData = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
100	    using T = typename GlobalSrcData::RawDType;
101	    using DynShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
102	    using SrcViewT = GlobalTensor<T, DynShape, DynStrideT, GlobalSrcData::layout>;
103	    using DstViewT = GlobalTensor<T, DynShape, DynStrideT, GlobalDstData::layout>;
104	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
105	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
106	
107	    if constexpr (isDynamicRow) {
108	        accTileData.RowMaskInternal = currentRows;
109	        recvTileData.RowMaskInternal = currentRows;
110	    }
111	    if constexpr (isDynamicCol) {
112	        accTileData.ColMaskInternal = currentCols;
113	        recvTileData.ColMaskInternal = currentCols;
114	    }
115	
116	    DynShape chunkShape(1, 1, 1, currentRows, currentCols);
117	    SrcViewT rootView(parallelGroup[rootIdx].data() + srcOffset, chunkShape, srcChunkStride);
118	    TLOAD(accTileData, rootView);
119	
120	    if (nranks == 1) {
121	        set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
122	        wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
123	    } else {
124	        set_flag(PIPE_MTE2, PIPE_V, EVENT_ID0);
125	        wait_flag(PIPE_MTE2, PIPE_V, EVENT_ID0);
126	        for (int r = 0; r < nranks; ++r) {
127	            if (r == rootIdx)
128	                continue;
129	            SrcViewT remoteView(parallelGroup[r].data() + srcOffset, chunkShape, srcChunkStride);
130	            TLOAD(recvTileData, remoteView);
131	            set_flag(PIPE_MTE2, PIPE_V, EVENT_ID1);
132	            wait_flag(PIPE_MTE2, PIPE_V, EVENT_ID1);
133	            detail::ReduceTiles(accTileData, recvTileData, op);
134	            set_flag(PIPE_V, PIPE_MTE2, EVENT_ID0);
135	            wait_flag(PIPE_V, PIPE_MTE2, EVENT_ID0);
136	        }
137	        set_flag(PIPE_V, PIPE_MTE3, EVENT_ID0);
138	        wait_flag(PIPE_V, PIPE_MTE3, EVENT_ID0);
139	    }
140	
141	    DstViewT dstView(dstGlobalData.data() + dstOffset, chunkShape, dstChunkStride);
142	    TSTORE(dstView, accTileData);
143	    set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
144	    wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
145	}
