147	// 2D sliding chunked reduce with single buffer
148	template <typename ParallelGroupType, typename GlobalDstData, typename TileData>
149	PTO_INTERNAL void TreduceChunkedSingle(
150	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& accTileData, TileData& recvTileData,
151	    ReduceOp op, int gShape0, int gShape1, int gShape2, int gShape3, int gShape4, int tileValidRow, int tileValidCol,
152	    int rootIdx, int nranks)
153	{
154	    using GlobalSrcData = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
155	    GlobalSrcData& refTensor = parallelGroup[rootIdx];
156	    const int srcStride0 = refTensor.GetStride(GlobalTensorDim::DIM_0);
157	    const int srcStride1 = refTensor.GetStride(GlobalTensorDim::DIM_1);
158	    const int srcStride2 = refTensor.GetStride(GlobalTensorDim::DIM_2);
159	    const int srcStride3 = refTensor.GetStride(GlobalTensorDim::DIM_3);
160	    const int srcStride4 = refTensor.GetStride(GlobalTensorDim::DIM_4);
161	    const int dstStride0 = dstGlobalData.GetStride(GlobalTensorDim::DIM_0);
162	    const int dstStride1 = dstGlobalData.GetStride(GlobalTensorDim::DIM_1);
163	    const int dstStride2 = dstGlobalData.GetStride(GlobalTensorDim::DIM_2);
164	    const int dstStride3 = dstGlobalData.GetStride(GlobalTensorDim::DIM_3);
165	    const int dstStride4 = dstGlobalData.GetStride(GlobalTensorDim::DIM_4);
166	
167	    using DynStride = Stride<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
168	    DynStride srcChunkStride(srcStride0, srcStride1, srcStride2, srcStride3, srcStride4);
169	    DynStride dstChunkStride(dstStride0, dstStride1, dstStride2, dstStride3, dstStride4);
170	
171	    for (int i0 = 0; i0 < gShape0; ++i0) {
172	        for (int i1 = 0; i1 < gShape1; ++i1) {
173	            for (int i2 = 0; i2 < gShape2; ++i2) {
174	                int64_t srcBase = static_cast<int64_t>(i0) * srcStride0 + static_cast<int64_t>(i1) * srcStride1 +
175	                                  static_cast<int64_t>(i2) * srcStride2;
176	                int64_t dstBase = static_cast<int64_t>(i0) * dstStride0 + static_cast<int64_t>(i1) * dstStride1 +
177	                                  static_cast<int64_t>(i2) * dstStride2;
178	                for (int rowOff = 0; rowOff < gShape3; rowOff += tileValidRow) {
179	                    int curRows = (rowOff + tileValidRow <= gShape3) ? tileValidRow : (gShape3 - rowOff);
180	                    for (int colOff = 0; colOff < gShape4; colOff += tileValidCol) {
181	                        int curCols = (colOff + tileValidCol <= gShape4) ? tileValidCol : (gShape4 - colOff);
182	                        int64_t srcOff = srcBase + static_cast<int64_t>(rowOff) * srcStride3 +
183	                                         static_cast<int64_t>(colOff) * srcStride4;
184	                        int64_t dstOff = dstBase + static_cast<int64_t>(rowOff) * dstStride3 +
185	                                         static_cast<int64_t>(colOff) * dstStride4;
186	                        TreduceProcessChunkSingle<ParallelGroupType, GlobalDstData, TileData>(
187	                            parallelGroup, dstGlobalData, accTileData, recvTileData, op, srcOff, dstOff, curRows,
188	                            curCols, srcChunkStride, dstChunkStride, rootIdx, nranks);
189	                    }
190	                }
191	            }
192	        }
193	    }
194	}
