196	// ============================================================================
197	// TREDUCE_IMPL: Reduce operation - root gathers and reduces data from all ranks
198	//
199	// The calling NPU is the root and gathers data from all ranks, performing
200	// element-wise reduction locally.
201	//
202	// When the GlobalTensor exceeds the UB tile capacity in rows and/or columns,
203	// the transfer is automatically chunked via 2D sliding:
204	//   - Outer dimensions (DIM_0, DIM_1, DIM_2) are iterated explicitly.
205	//   - DIM_3 (rows) is split into tileValidRow-sized chunks.
206	//   - DIM_4 (cols) is split into tileValidCol-sized chunks.
207	//
208	// For each chunk, the full reduce pipeline is executed:
209	//   1. Load root's chunk into accTileData
210	//   2. For each remote rank: TLOAD chunk into recvTileData, reduce into acc
211	//   3. Store reduced chunk to dstGlobalData
212	//
213	// Constraints for chunked mode:
214	//   - If TileData has static ValidRow, shape3 must be divisible by ValidRow.
215	//     Use DYNAMIC ValidRow for partial row chunk support.
216	//   - If TileData has static ValidCol, shape4 must be divisible by ValidCol.
217	//     Use DYNAMIC ValidCol for partial column chunk support.
218	//   - All ranks in the ParallelGroup are assumed to have the same shape/strides.
219	// ============================================================================
220	
221	template <typename ParallelGroupType, typename GlobalDstData, typename TileData>
222	PTO_INTERNAL void TREDUCE_IMPL(
223	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& accTileData, TileData& recvTileData,
224	    ReduceOp op)
225	{
226	    using GlobalSrcData = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
227	    using T = typename GlobalSrcData::RawDType;
228	
229	    static_assert(std::is_same_v<T, typename GlobalDstData::RawDType>, "TREDUCE: GlobalData type mismatch!");
230	    static_assert(
231	        std::is_same_v<T, typename TileData::DType>,
232	        "TREDUCE: TileData element type must match GlobalData element type");
233	
234	    const int rootRank = parallelGroup.GetRootIdx();
235	    const int groupSize = parallelGroup.GetSize();
236	
237	    PTO_ASSERT(groupSize > 0, "ParallelGroup size must be greater than 0!");
238	    PTO_ASSERT(rootRank >= 0 && rootRank < groupSize, "rootIdx must be in range [0, nranks)!");
239	
240	    GlobalSrcData& refTensor = parallelGroup[rootRank];
241	    const int gShape0 = refTensor.GetShape(GlobalTensorDim::DIM_0);
242	    const int gShape1 = refTensor.GetShape(GlobalTensorDim::DIM_1);
243	    const int gShape2 = refTensor.GetShape(GlobalTensorDim::DIM_2);
244	    const int gShape3 = refTensor.GetShape(GlobalTensorDim::DIM_3);
245	    const int gShape4 = refTensor.GetShape(GlobalTensorDim::DIM_4);
246	
247	    const int64_t totalRows = static_cast<int64_t>(gShape0) * gShape1 * gShape2 * gShape3;
248	    const int chunkRows = accTileData.GetValidRow();
249	    const int chunkCols = accTileData.GetValidCol();
250	
251	    PTO_ASSERT(chunkRows > 0, "TREDUCE: tileValidRow must be greater than 0");
252	    PTO_ASSERT(chunkCols > 0, "TREDUCE: tileValidCol must be greater than 0");
253	
254	    if (totalRows == 0 || gShape4 == 0) {
255	        return;
256	    }
257	
258	    if (totalRows <= chunkRows && gShape4 <= chunkCols) {
259	        TreduceSimple<ParallelGroupType, GlobalDstData, TileData>(
260	            parallelGroup, dstGlobalData, accTileData, recvTileData, op, rootRank, groupSize);
261	        return;
262	    }
263	
264	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
265	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
266	
267	    if constexpr (!isDynamicRow) {
268	        PTO_ASSERT(
269	            gShape3 % chunkRows == 0,
270	            "TREDUCE chunked: shape3 must be divisible by tile ValidRow when ValidRow is static. "
271	            "Use a Tile with DYNAMIC ValidRow for partial row chunk support.");
272	    }
273	    if constexpr (!isDynamicCol) {
274	        PTO_ASSERT(
275	            gShape4 % chunkCols == 0,
276	            "TREDUCE chunked: shape4 must be divisible by tile ValidCol when ValidCol is static. "
277	            "Use a Tile with DYNAMIC ValidCol for partial column chunk support.");
278	    }
279	
280	    TreduceChunkedSingle<ParallelGroupType, GlobalDstData, TileData>(
281	        parallelGroup, dstGlobalData, accTileData, recvTileData, op, gShape0, gShape1, gShape2, gShape3, gShape4,
282	        chunkRows, chunkCols, rootRank, groupSize);
283	}
284	
285	// ============================================================================
286	// Ping-pong helpers for TREDUCE
287	// ============================================================================
288	
289	// Simple reduce path with ping-pong: entire data fits in one tile
290	template <typename ParallelGroupType, typename GlobalDstData, typename TileData>
291	PTO_INTERNAL void TreduceSimplePingPong(
292	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& accTileData, TileData& pingTile,
293	    TileData& pongTile, ReduceOp op, int rootIdx, int nranks, int numRemote)
294	{
295	    auto& rootTensor = parallelGroup[rootIdx];
296	    if (nranks == 1) {
297	        TLOAD(accTileData, rootTensor);
298	        PtoSetWaitFlag<PIPE_MTE2, PIPE_MTE3>();
299	        TSTORE(dstGlobalData, accTileData);
300	        PtoSetWaitFlag<PIPE_MTE3, PIPE_MTE2>();
301	        return;
302	    }
303	
304	    TLOAD(accTileData, rootTensor);
305	    set_flag(PIPE_MTE2, PIPE_V, EVENT_ID0);
306	    TLOAD(pingTile, parallelGroup[detail::GetRemoteRank(rootIdx, 0)]);
307	    set_flag(PIPE_MTE2, PIPE_V, EVENT_ID1);
308	    wait_flag(PIPE_MTE2, PIPE_V, EVENT_ID0);
309	
310	    for (int i = 0; i < numRemote; ++i) {
311	        const bool hasNext = (i + 1 < numRemote);
312	        const bool usePing = ((i & 1) == 0);
313	        TileData& currentTile = usePing ? pingTile : pongTile;
314	        TileData& nextTile = usePing ? pongTile : pingTile;
315	        const auto currentEvent = usePing ? EVENT_ID1 : EVENT_ID2;
316	        const auto nextEvent = usePing ? EVENT_ID2 : EVENT_ID1;
317	        if (hasNext) {
318	            TLOAD(nextTile, parallelGroup[detail::GetRemoteRank(rootIdx, i + 1)]);
319	            set_flag(PIPE_MTE2, PIPE_V, nextEvent);
320	        }
321	        wait_flag(PIPE_MTE2, PIPE_V, currentEvent);
322	        detail::ReduceTiles(accTileData, currentTile, op);
323	        if (hasNext) {
324	            set_flag(PIPE_V, PIPE_MTE2, EVENT_ID0);
325	            wait_flag(PIPE_V, PIPE_MTE2, EVENT_ID0);
326	        } else {
327	            set_flag(PIPE_V, PIPE_MTE3, EVENT_ID0);
328	            wait_flag(PIPE_V, PIPE_MTE3, EVENT_ID0);
329	        }
330	    }
331	
332	    TSTORE(dstGlobalData, accTileData);
333	    set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
334	    wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
335	}
336	
337	// Ping-pong reduce loop over remote ranks for one chunk (used in chunked path)
338	template <typename ParallelGroupType, typename TileData, typename DynStrideT>
339	PTO_INTERNAL void TreducePingPongLoop(
340	    ParallelGroupType& parallelGroup, TileData& accTileData, TileData& pingTile, TileData& pongTile, ReduceOp op,
341	    int64_t srcOffset, int currentRows, int currentCols, const DynStrideT& srcChunkStride, int rootIdx, int numRemote)
342	{
343	    using GlobalSrcData = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
344	    using T = typename GlobalSrcData::RawDType;
345	    using DynShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
346	    using SrcViewT = GlobalTensor<T, DynShape, DynStrideT, GlobalSrcData::layout>;
347	    DynShape chunkShape(1, 1, 1, currentRows, currentCols);
348	
349	    const int firstRemoteRank = detail::GetRemoteRank(rootIdx, 0);
350	    set_flag(PIPE_MTE2, PIPE_V, EVENT_ID0);
351	    SrcViewT firstView(parallelGroup[firstRemoteRank].data() + srcOffset, chunkShape, srcChunkStride);
352	    TLOAD(pingTile, firstView);
353	    set_flag(PIPE_MTE2, PIPE_V, EVENT_ID1);
354	    wait_flag(PIPE_MTE2, PIPE_V, EVENT_ID0);
355	
356	    for (int i = 0; i < numRemote; ++i) {
357	        const bool scheduleNext = (i + 1 < numRemote);
358	        const bool currentIsPing = ((i & 1) == 0);
359	        TileData& currentTile = currentIsPing ? pingTile : pongTile;
360	        TileData& nextTile = currentIsPing ? pongTile : pingTile;
361	        const event_t currentReady = currentIsPing ? EVENT_ID1 : EVENT_ID2;
362	        const event_t nextReady = currentIsPing ? EVENT_ID2 : EVENT_ID1;
363	        if (scheduleNext) {
364	            const int nextRemoteRank = detail::GetRemoteRank(rootIdx, i + 1);
365	            SrcViewT nextView(parallelGroup[nextRemoteRank].data() + srcOffset, chunkShape, srcChunkStride);
366	            TLOAD(nextTile, nextView);
367	            set_flag(PIPE_MTE2, PIPE_V, nextReady);
368	        }
369	        wait_flag(PIPE_MTE2, PIPE_V, currentReady);
370	        detail::ReduceTiles(accTileData, currentTile, op);
371	        if (!scheduleNext) {
372	            set_flag(PIPE_V, PIPE_MTE3, EVENT_ID0);
373	            wait_flag(PIPE_V, PIPE_MTE3, EVENT_ID0);
374	            continue;
375	        }
376	        set_flag(PIPE_V, PIPE_MTE2, EVENT_ID0);
377	        wait_flag(PIPE_V, PIPE_MTE2, EVENT_ID0);
378	    }
379	}
380	
381	// Process one chunk's full reduce pipeline with ping-pong double buffering
382	template <typename ParallelGroupType, typename GlobalDstData, typename TileData, typename DynStrideT>
383	PTO_INTERNAL void TreduceProcessChunkPingPong(
384	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& accTileData, TileData& pingTile,
385	    TileData& pongTile, ReduceOp op, int64_t srcOffset, int64_t dstOffset, int currentRows, int currentCols,
386	    const DynStrideT& srcChunkStride, const DynStrideT& dstChunkStride, int rootIdx, int nranks, int numRemote)
387	{
388	    using GlobalSrcData = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
389	    using ElemT = typename GlobalSrcData::RawDType;
390	    using DynShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
391	    using SrcViewT = GlobalTensor<ElemT, DynShape, DynStrideT, GlobalSrcData::layout>;
392	    using DstViewT = GlobalTensor<ElemT, DynShape, DynStrideT, GlobalDstData::layout>;
393	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
394	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
395	
396	    if constexpr (isDynamicRow) {
397	        accTileData.RowMaskInternal = currentRows;
398	        pingTile.RowMaskInternal = currentRows;
399	        pongTile.RowMaskInternal = currentRows;
400	    }
401	    if constexpr (isDynamicCol) {
402	        accTileData.ColMaskInternal = currentCols;
403	        pingTile.ColMaskInternal = currentCols;
404	        pongTile.ColMaskInternal = currentCols;
405	    }
406	
407	    DynShape chunkShape(1, 1, 1, currentRows, currentCols);
408	    SrcViewT rootView(parallelGroup[rootIdx].data() + srcOffset, chunkShape, srcChunkStride);
409	    TLOAD(accTileData, rootView);
410	
411	    if (nranks == 1) {
412	        set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
413	        wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
414	    } else {
415	        TreducePingPongLoop<ParallelGroupType, TileData>(
416	            parallelGroup, accTileData, pingTile, pongTile, op, srcOffset, currentRows, currentCols, srcChunkStride,
417	            rootIdx, numRemote);
418	    }
419	
420	    DstViewT dstView(dstGlobalData.data() + dstOffset, chunkShape, dstChunkStride);
421	    TSTORE(dstView, accTileData);
422	    set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
423	    wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
424	}
425	
426	// 2D sliding chunked reduce with ping-pong double buffering
427	template <typename ParallelGroupType, typename GlobalDstData, typename TileData>
428	PTO_INTERNAL void TreduceChunkedPingPong(
429	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& accTileData, TileData& pingTile,
430	    TileData& pongTile, ReduceOp op, int gShape0, int gShape1, int gShape2, int gShape3, int gShape4, int tileValidRow,
431	    int tileValidCol, int rootIdx, int nranks, int numRemote)
432	{
433	    using GlobalSrcData = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
434	    GlobalSrcData& refTensor = parallelGroup[rootIdx];
435	    const int srcStride[5] = {
436	        static_cast<int>(refTensor.GetStride(GlobalTensorDim::DIM_0)),
437	        static_cast<int>(refTensor.GetStride(GlobalTensorDim::DIM_1)),
438	        static_cast<int>(refTensor.GetStride(GlobalTensorDim::DIM_2)),
439	        static_cast<int>(refTensor.GetStride(GlobalTensorDim::DIM_3)),
440	        static_cast<int>(refTensor.GetStride(GlobalTensorDim::DIM_4))};
441	    const int dstStride[5] = {
442	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_0)),
443	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_1)),
444	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_2)),
445	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_3)),
446	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_4))};
447	
448	    using DynStride = Stride<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
449	    DynStride srcChunkStride(srcStride[0], srcStride[1], srcStride[2], srcStride[3], srcStride[4]);
450	    DynStride dstChunkStride(dstStride[0], dstStride[1], dstStride[2], dstStride[3], dstStride[4]);
451	
452	    for (int dim0 = 0; dim0 < gShape0; ++dim0) {
453	        for (int dim1 = 0; dim1 < gShape1; ++dim1) {
454	            for (int dim2 = 0; dim2 < gShape2; ++dim2) {
455	                const int64_t srcBase = static_cast<int64_t>(dim0) * srcStride[0] +
456	                                        static_cast<int64_t>(dim1) * srcStride[1] +
457	                                        static_cast<int64_t>(dim2) * srcStride[2];
458	                const int64_t dstBase = static_cast<int64_t>(dim0) * dstStride[0] +
459	                                        static_cast<int64_t>(dim1) * dstStride[1] +
460	                                        static_cast<int64_t>(dim2) * dstStride[2];
461	                int rowCursor = 0;
462	                while (rowCursor < gShape3) {
463	                    const int rowRemain = gShape3 - rowCursor;
464	                    const int curRows = (rowRemain < tileValidRow) ? rowRemain : tileValidRow;
465	                    int colCursor = 0;
466	                    while (colCursor < gShape4) {
467	                        const int colRemain = gShape4 - colCursor;
468	                        const int curCols = (colRemain < tileValidCol) ? colRemain : tileValidCol;
469	                        const int64_t srcOff = srcBase + static_cast<int64_t>(rowCursor) * srcStride[3] +
470	                                               static_cast<int64_t>(colCursor) * srcStride[4];
471	                        const int64_t dstOff = dstBase + static_cast<int64_t>(rowCursor) * dstStride[3] +
472	                                               static_cast<int64_t>(colCursor) * dstStride[4];
473	                        TreduceProcessChunkPingPong<ParallelGroupType, GlobalDstData, TileData>(
474	                            parallelGroup, dstGlobalData, accTileData, pingTile, pongTile, op, srcOff, dstOff, curRows,
475	                            curCols, srcChunkStride, dstChunkStride, rootIdx, nranks, numRemote);
476	                        colCursor += tileValidCol;
477	                    }
478	                    rowCursor += tileValidRow;
479	                }
480	            }
481	        }
482	    }
483	}
484	
485	// ============================================================================
486	// TREDUCE_IMPL (ping-pong): Reduce operation with double buffering
487	//
488	// The calling NPU is the root and gathers data from all ranks, performing
489	// element-wise reduction locally. Uses ping-pong double buffering to overlap
490	// remote data transfer (TLOAD) with reduction computation.
491	//
492	// When the GlobalTensor exceeds the UB tile capacity, the operation is
493	// automatically chunked via 2D sliding (same as TREDUCE_IMPL). Within each
494	// chunk, ping-pong double buffering is applied to the remote rank reduction:
495	//
496	// Timeline without ping-pong:
497	//   [TLOAD remote0] -> [Reduce] -> [TLOAD remote1] -> [Reduce] -> ...
498	//
499	// Timeline with ping-pong (overlap TLOAD[i+1] with Reduce[i]):
500	//   [TLOAD remote0] -> [Reduce remote0 | TLOAD remote1] -> [Reduce remote1 | TLOAD remote2] -> ...
501	//
502	// Constraints: same as TREDUCE_IMPL for chunked mode.
503	// ============================================================================
504	template <typename ParallelGroupType, typename GlobalDstData, typename TileData>
505	PTO_INTERNAL void TREDUCE_IMPL(
506	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& accTileData, TileData& pingTile,
507	    TileData& pongTile, ReduceOp op)
508	{
509	    using GlobalSrcData = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
510	    using T = typename GlobalSrcData::RawDType;
511	
512	    static_assert(std::is_same_v<T, typename GlobalDstData::RawDType>, "TREDUCE: GlobalData type mismatch!");
513	    static_assert(
514	        std::is_same_v<T, typename TileData::DType>,
515	        "TREDUCE: TileData element type must match GlobalData element type");
516	
517	    const int rootIdx = parallelGroup.GetRootIdx();
518	    const int nranks = parallelGroup.GetSize();
519	
520	    PTO_ASSERT(nranks > 0, "ParallelGroup size must be greater than 0!");
521	    PTO_ASSERT(rootIdx >= 0 && rootIdx < nranks, "rootIdx must be in range [0, nranks)!");
522	
523	    GlobalSrcData& refTensor = parallelGroup[rootIdx];
524	    const int gShape0 = refTensor.GetShape(GlobalTensorDim::DIM_0);
525	    const int gShape1 = refTensor.GetShape(GlobalTensorDim::DIM_1);
526	    const int gShape2 = refTensor.GetShape(GlobalTensorDim::DIM_2);
527	    const int gShape3 = refTensor.GetShape(GlobalTensorDim::DIM_3);
528	    const int gShape4 = refTensor.GetShape(GlobalTensorDim::DIM_4);
529	
530	    const int64_t totalRows = static_cast<int64_t>(gShape0) * gShape1 * gShape2 * gShape3;
531	    const int tileValidRow = accTileData.GetValidRow();
532	    const int tileValidCol = accTileData.GetValidCol();
533	
534	    PTO_ASSERT(tileValidRow > 0, "TREDUCE: tileValidRow must be greater than 0");
535	    PTO_ASSERT(tileValidCol > 0, "TREDUCE: tileValidCol must be greater than 0");
536	
537	    if (totalRows == 0 || gShape4 == 0) {
538	        return;
539	    }
540	
541	    const int remoteCount = nranks - 1;
542	
543	    if (totalRows <= tileValidRow && gShape4 <= tileValidCol) {
544	        TreduceSimplePingPong<ParallelGroupType, GlobalDstData, TileData>(
545	            parallelGroup, dstGlobalData, accTileData, pingTile, pongTile, op, rootIdx, nranks, remoteCount);
546	        return;
547	    }
548	
549	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
550	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
551	
552	    if constexpr (!isDynamicRow) {
553	        PTO_ASSERT(
554	            gShape3 % tileValidRow == 0,
555	            "TREDUCE chunked: shape3 must be divisible by tile ValidRow when ValidRow is static. "
556	            "Use a Tile with DYNAMIC ValidRow for partial row chunk support.");
557	    }
558	    if constexpr (!isDynamicCol) {
559	        PTO_ASSERT(
560	            gShape4 % tileValidCol == 0,
561	            "TREDUCE chunked: shape4 must be divisible by tile ValidCol when ValidCol is static. "
562	            "Use a Tile with DYNAMIC ValidCol for partial column chunk support.");
563	    }
564	
565	    TreduceChunkedPingPong<ParallelGroupType, GlobalDstData, TileData>(
566	        parallelGroup, dstGlobalData, accTileData, pingTile, pongTile, op, gShape0, gShape1, gShape2, gShape3, gShape4,
567	        tileValidRow, tileValidCol, rootIdx, nranks, remoteCount);
568	}
569	
570	// CCU engine is only available on A5 hardware.  Stub mirrors the URMA branch
571	// in `a2a3/async/TPutAsync.hpp`: the template name must exist for the
572	// qualified template-id `::pto::comm::TREDUCE_CCU_IMPL<engine>(...)` in
573	// pto_comm_inst.hpp to parse on A2/A3; the static_assert is dependent on the
574	// `engine` parameter and only fires if the overload is actually instantiated.
575	// `a5/TReduce.hpp` defines `PTO_COMM_A5_TREDUCE_PROVIDED` before including
576	// this header so the stub is omitted on A5 builds, where the real
577	// `TREDUCE_CCU_IMPL` overload lives.  Otherwise the generic `Args&&...` pack
578	// would compete with the real `T&` parameters in `pto::comm`'s overload set
579	// and could win under partial ordering on some compilers.
580	#ifndef PTO_COMM_A5_TREDUCE_PROVIDED
581	template <CollEngine engine = CollEngine::CCU, typename... Args>
582	PTO_INTERNAL void TREDUCE_CCU_IMPL(Args&&...)
583	{
584	    static_assert(
585	        engine != CollEngine::CCU, "TREDUCE<CollEngine::CCU> requires A5 hardware; "
586	                                   "CCU engine is not available on A2/A3.");
587	}
588	#endif // PTO_COMM_A5_TREDUCE_PROVIDED
589	
590	} // namespace comm
591	} // namespace pto
592	
593	#endif // PTO_COMM_TREDUCE_HPP
