25	// Ping-pong double-buffering state for chunked TSCATTER transfers
26	struct TscatterPingPongState {
27	    bool usePing = true;
28	    bool hasPending = false;
29	    int64_t pendingDstOffset = 0;
30	    int pendingRank = 0;
31	    int pendingRows = 0;
32	    int pendingCols = 0;
33	};
34	
35	// Simple scatter path: per-rank data fits in a single tile, loop over all ranks
36	template <typename ParallelGroupType, typename GlobalSrcData, typename TileData>
37	PTO_INTERNAL void TscatterSimple(
38	    ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& stagingTileData, int gShape0, int gShape1,
39	    int gShape2, int gShape3, int gShape4, int nranks, int perRankRows)
40	{
41	    using T = typename GlobalSrcData::RawDType;
42	    const int srcStride3 = srcGlobalData.GetStride(GlobalTensorDim::DIM_3);
43	
44	    using DynShape5D = Shape<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
45	    using DynStride = Stride<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
46	    using SrcViewT = GlobalTensor<T, DynShape5D, DynStride, GlobalSrcData::layout>;
47	
48	    DynShape5D perRankShape(gShape0, gShape1, gShape2, gShape3, gShape4);
49	    DynStride srcViewStride(
50	        srcGlobalData.GetStride(GlobalTensorDim::DIM_0), srcGlobalData.GetStride(GlobalTensorDim::DIM_1),
51	        srcGlobalData.GetStride(GlobalTensorDim::DIM_2), srcStride3, srcGlobalData.GetStride(GlobalTensorDim::DIM_4));
52	
53	    for (int r = 0; r < nranks; ++r) {
54	        int64_t srcOffset = static_cast<int64_t>(r) * perRankRows * srcStride3;
55	        SrcViewT srcView(srcGlobalData.data() + srcOffset, perRankShape, srcViewStride);
56	        TLOAD(stagingTileData, srcView);
57	        set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
58	        wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
59	        TSTORE(parallelGroup[r], stagingTileData);
60	        set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
61	        wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
62	    }
63	}
