105	// 2D sliding chunked scatter with single buffer
106	template <typename ParallelGroupType, typename GlobalSrcData, typename TileData>
107	PTO_INTERNAL void TscatterChunkedSingle(
108	    ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& stagingTileData, int gShape0, int gShape1,
109	    int gShape2, int gShape3, int gShape4, int tileValidRow, int tileValidCol, int nranks, int perRankRows)
110	{
111	    using GlobalDstData = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
112	    using T = typename GlobalSrcData::RawDType;
113	
114	    const int srcStep[5] = {
115	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_0)),
116	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_1)),
117	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_2)),
118	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_3)),
119	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_4))};
120	    const int dstStep[5] = {
121	        static_cast<int>(parallelGroup[0].GetStride(GlobalTensorDim::DIM_0)),
122	        static_cast<int>(parallelGroup[0].GetStride(GlobalTensorDim::DIM_1)),
123	        static_cast<int>(parallelGroup[0].GetStride(GlobalTensorDim::DIM_2)),
124	        static_cast<int>(parallelGroup[0].GetStride(GlobalTensorDim::DIM_3)),
125	        static_cast<int>(parallelGroup[0].GetStride(GlobalTensorDim::DIM_4))};
126	
127	    for (int r = 0; r < nranks; ++r) {
128	        int64_t rankSrcBase = static_cast<int64_t>(r) * perRankRows * srcStep[3];
129	        for (int i0 = 0; i0 < gShape0; ++i0) {
130	            for (int i1 = 0; i1 < gShape1; ++i1) {
131	                for (int i2 = 0; i2 < gShape2; ++i2) {
132	                    int64_t srcBase = rankSrcBase + static_cast<int64_t>(i0) * srcStep[0] +
133	                                      static_cast<int64_t>(i1) * srcStep[1] + static_cast<int64_t>(i2) * srcStep[2];
134	                    int64_t dstBase = static_cast<int64_t>(i0) * dstStep[0] + static_cast<int64_t>(i1) * dstStep[1] +
135	                                      static_cast<int64_t>(i2) * dstStep[2];
136	                    TscatterChunkedRowColLoop<TileData, T, GlobalSrcData::layout, GlobalDstData::layout>(
137	                        stagingTileData, srcGlobalData.data(), parallelGroup[r].data(), srcBase, dstBase, gShape3,
138	                        gShape4, tileValidRow, tileValidCol, srcStep, dstStep);
139	                }
140	            }
141	        }
142	    }
143	}
