145	// ============================================================================
146	// TSCATTER_IMPL: Scatter operation - root distributes data to all ranks
147	//
148	// The calling NPU (root) splits local source data along DIM_3 (row dimension)
149	// and distributes the portions to each rank in the parallel group.
150	// This is the inverse of TGATHER.
151	//
152	// The source tensor has shape (D0, D1, D2, N*H, W). Each rank r receives
153	// rows [r*H, (r+1)*H), i.e., per-rank data of shape (D0, D1, D2, H, W).
154	//
155	// When the per-rank data exceeds the UB tile capacity in rows and/or columns,
156	// the transfer is automatically chunked via 2D sliding:
157	//   - Outer dimensions (DIM_0, DIM_1, DIM_2) are iterated explicitly.
158	//   - DIM_3 (rows) is split into tileValidRow-sized chunks.
159	//   - DIM_4 (cols) is split into tileValidCol-sized chunks.
160	//
161	// Constraints for chunked mode:
162	//   - If TileData has static ValidRow, per-rank DIM_3 must be divisible by ValidRow.
163	//   - If TileData has static ValidCol, DIM_4 must be divisible by ValidCol.
164	//   - All destination tensors in the ParallelGroup are assumed to have the same shape/strides.
165	// ============================================================================
166	
167	template <typename ParallelGroupType, typename GlobalSrcData, typename TileData>
168	PTO_INTERNAL void TSCATTER_IMPL(
169	    ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& stagingTileData)
170	{
171	    using GlobalDstData = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
172	    using T = typename GlobalSrcData::RawDType;
173	
174	    static_assert(std::is_same_v<T, typename GlobalDstData::RawDType>, "TSCATTER: GlobalData type mismatch!");
175	    static_assert(
176	        std::is_same_v<T, typename TileData::DType>,
177	        "TSCATTER: TileData element type must match GlobalData element type");
178	    static_assert(GlobalSrcData::layout == GlobalDstData::layout, "TSCATTER: src/dst layout mismatch");
179	
180	    const int nranks = parallelGroup.GetSize();
181	    const int rootIdx = parallelGroup.GetRootIdx();
182	
183	    PTO_ASSERT(nranks > 0, "ParallelGroup size must be greater than 0!");
184	    PTO_ASSERT(rootIdx >= 0 && rootIdx < nranks, "rootIdx must be in range [0, nranks)!");
185	
186	    const int gShape0 = parallelGroup[0].GetShape(GlobalTensorDim::DIM_0);
187	    const int gShape1 = parallelGroup[0].GetShape(GlobalTensorDim::DIM_1);
188	    const int gShape2 = parallelGroup[0].GetShape(GlobalTensorDim::DIM_2);
189	    const int gShape3 = parallelGroup[0].GetShape(GlobalTensorDim::DIM_3);
190	    const int gShape4 = parallelGroup[0].GetShape(GlobalTensorDim::DIM_4);
191	
192	    const int perRankRows = gShape3;
193	    const int64_t totalRows = static_cast<int64_t>(gShape0) * gShape1 * gShape2 * gShape3;
194	    const int tileValidRow = stagingTileData.GetValidRow();
195	    const int tileValidCol = stagingTileData.GetValidCol();
196	
197	    PTO_ASSERT(tileValidRow > 0, "TSCATTER: tileValidRow must be greater than 0");
198	    PTO_ASSERT(tileValidCol > 0, "TSCATTER: tileValidCol must be greater than 0");
199	
200	    if (totalRows == 0 || gShape4 == 0) {
201	        return;
202	    }
203	
204	    // Simple path: per-rank data fits in UB tile
205	    if (totalRows <= tileValidRow && gShape4 <= tileValidCol) {
206	        TscatterSimple<ParallelGroupType, GlobalSrcData, TileData>(
207	            parallelGroup, srcGlobalData, stagingTileData, gShape0, gShape1, gShape2, gShape3, gShape4, nranks,
208	            perRankRows);
209	        return;
210	    }
211	
212	    // 2D sliding chunked path
213	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
214	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
215	
216	    if constexpr (!isDynamicRow) {
217	        PTO_ASSERT(
218	            gShape3 % tileValidRow == 0,
219	            "TSCATTER chunked: per-rank DIM_3 must be divisible by tile ValidRow when static. "
220	            "Use a Tile with DYNAMIC ValidRow for partial row chunk support.");
221	    }
222	    if constexpr (!isDynamicCol) {
223	        PTO_ASSERT(
224	            gShape4 % tileValidCol == 0, "TSCATTER chunked: DIM_4 must be divisible by tile ValidCol when static. "
225	                                         "Use a Tile with DYNAMIC ValidCol for partial column chunk support.");
226	    }
227	
228	    TscatterChunkedSingle<ParallelGroupType, GlobalSrcData, TileData>(
229	        parallelGroup, srcGlobalData, stagingTileData, gShape0, gShape1, gShape2, gShape3, gShape4, tileValidRow,
230	        tileValidCol, nranks, perRankRows);
231	}
232	
233	// Process one chunk iteration with ping-pong double buffering for scatter
234	template <typename ParallelGroupType, typename GlobalSrcData, typename TileData, typename DynStrideT>
235	PTO_INTERNAL void TscatterPingPongProcessChunk(
236	    ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile,
237	    int64_t srcOffset, int64_t dstOffset, int currentRows, int currentCols, const DynStrideT& srcChunkStride,
238	    const DynStrideT& dstChunkStride, int rank, TscatterPingPongState& state)
239	{
240	    using GlobalDstData = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
241	    using T = typename GlobalSrcData::RawDType;
242	    using DynShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
243	    using SrcViewT = GlobalTensor<T, DynShape, DynStrideT, GlobalSrcData::layout>;
244	    using DstViewT = GlobalTensor<T, DynShape, DynStrideT, GlobalDstData::layout>;
245	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
246	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
247	
248	    TileData& loadTile = state.usePing ? pingTile : pongTile;
249	    event_t curEvent = state.usePing ? EVENT_ID0 : EVENT_ID1;
250	
251	    if constexpr (isDynamicRow)
252	        loadTile.RowMaskInternal = currentRows;
253	    if constexpr (isDynamicCol)
254	        loadTile.ColMaskInternal = currentCols;
255	
256	    DynShape chunkShape(1, 1, 1, currentRows, currentCols);
257	    SrcViewT srcView(srcGlobalData.data() + srcOffset, chunkShape, srcChunkStride);
258	
259	    if (state.hasPending) {
260	        TileData& storeTile = state.usePing ? pongTile : pingTile;
261	        event_t prevEvent = state.usePing ? EVENT_ID1 : EVENT_ID0;
262	
263	        wait_flag(PIPE_MTE2, PIPE_MTE3, prevEvent);
264	
265	        DynShape pendShape(1, 1, 1, state.pendingRows, state.pendingCols);
266	        DstViewT dstView(parallelGroup[state.pendingRank].data() + state.pendingDstOffset, pendShape, dstChunkStride);
267	
268	        TSTORE(dstView, storeTile);
269	        TLOAD(loadTile, srcView);
270	
271	        set_flag(PIPE_MTE3, PIPE_MTE2, prevEvent);
272	        set_flag(PIPE_MTE2, PIPE_MTE3, curEvent);
273	
274	        wait_flag(PIPE_MTE3, PIPE_MTE2, prevEvent);
275	    } else {
276	        TLOAD(loadTile, srcView);
277	        set_flag(PIPE_MTE2, PIPE_MTE3, curEvent);
278	    }
279	
280	    state.pendingDstOffset = dstOffset;
281	    state.pendingRank = rank;
282	    state.pendingRows = currentRows;
283	    state.pendingCols = currentCols;
284	    state.hasPending = true;
285	    state.usePing = !state.usePing;
286	}
287	
288	// Drain the last pending TSTORE after the chunked ping-pong loop completes
289	template <typename ParallelGroupType, typename TileData, typename DynStrideT>
290	PTO_INTERNAL void TscatterPingPongEpilogue(
291	    ParallelGroupType& parallelGroup, TileData& pingTile, TileData& pongTile, const TscatterPingPongState& state,
292	    const DynStrideT& dstChunkStride)
293	{
294	    if (!state.hasPending)
295	        return;
296	    using GlobalDstData = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
297	    using T = typename GlobalDstData::RawDType;
298	    using DynShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
299	    using DstViewT = GlobalTensor<T, DynShape, DynStrideT, GlobalDstData::layout>;
300	
301	    TileData& lastTile = state.usePing ? pongTile : pingTile;
302	    event_t lastEvent = state.usePing ? EVENT_ID1 : EVENT_ID0;
303	
304	    wait_flag(PIPE_MTE2, PIPE_MTE3, lastEvent);
305	    DynShape lastShape(1, 1, 1, state.pendingRows, state.pendingCols);
306	    DstViewT dstView(parallelGroup[state.pendingRank].data() + state.pendingDstOffset, lastShape, dstChunkStride);
307	    TSTORE(dstView, lastTile);
308	    set_flag(PIPE_MTE3, PIPE_MTE2, lastEvent);
309	    wait_flag(PIPE_MTE3, PIPE_MTE2, lastEvent);
310	}
311	
312	// 2D sliding chunked scatter with ping-pong double buffering
313	template <typename ParallelGroupType, typename GlobalSrcData, typename TileData>
314	PTO_INTERNAL void TscatterChunkedPingPong(
315	    ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile, int gShape0,
316	    int gShape1, int gShape2, int gShape3, int gShape4, int tileValidRow, int tileValidCol, int nranks, int perRankRows)
317	{
318	    const int srcStep0 = srcGlobalData.GetStride(GlobalTensorDim::DIM_0);
319	    const int srcStep1 = srcGlobalData.GetStride(GlobalTensorDim::DIM_1);
320	    const int srcStep2 = srcGlobalData.GetStride(GlobalTensorDim::DIM_2);
321	    const int srcStep3 = srcGlobalData.GetStride(GlobalTensorDim::DIM_3);
322	    const int srcStep4 = srcGlobalData.GetStride(GlobalTensorDim::DIM_4);
323	    const int dstStep0 = parallelGroup[0].GetStride(GlobalTensorDim::DIM_0);
324	    const int dstStep1 = parallelGroup[0].GetStride(GlobalTensorDim::DIM_1);
325	    const int dstStep2 = parallelGroup[0].GetStride(GlobalTensorDim::DIM_2);
326	    const int dstStep3 = parallelGroup[0].GetStride(GlobalTensorDim::DIM_3);
327	    const int dstStep4 = parallelGroup[0].GetStride(GlobalTensorDim::DIM_4);
328	
329	    using DynStride = Stride<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
330	    DynStride srcChunkStride(srcStep0, srcStep1, srcStep2, srcStep3, srcStep4);
331	    DynStride dstChunkStride(dstStep0, dstStep1, dstStep2, dstStep3, dstStep4);
332	    TscatterPingPongState state;
333	
334	    for (int r = 0; r < nranks; ++r) {
335	        int64_t rankSrcBase = static_cast<int64_t>(r) * perRankRows * srcStep3;
336	        for (int i0 = 0; i0 < gShape0; ++i0) {
337	            for (int i1 = 0; i1 < gShape1; ++i1) {
338	                for (int i2 = 0; i2 < gShape2; ++i2) {
339	                    int64_t srcBase = rankSrcBase + static_cast<int64_t>(i0) * srcStep0 +
340	                                      static_cast<int64_t>(i1) * srcStep1 + static_cast<int64_t>(i2) * srcStep2;
341	                    int64_t dstBase = static_cast<int64_t>(i0) * dstStep0 + static_cast<int64_t>(i1) * dstStep1 +
342	                                      static_cast<int64_t>(i2) * dstStep2;
343	                    for (int rowOff = 0; rowOff < gShape3; rowOff += tileValidRow) {
344	                        int curRows = (rowOff + tileValidRow <= gShape3) ? tileValidRow : (gShape3 - rowOff);
345	                        for (int colOff = 0; colOff < gShape4; colOff += tileValidCol) {
346	                            int curCols = (colOff + tileValidCol <= gShape4) ? tileValidCol : (gShape4 - colOff);
347	                            int64_t srcOff = srcBase + static_cast<int64_t>(rowOff) * srcStep3 +
348	                                             static_cast<int64_t>(colOff) * srcStep4;
349	                            int64_t dstOff = dstBase + static_cast<int64_t>(rowOff) * dstStep3 +
350	                                             static_cast<int64_t>(colOff) * dstStep4;
351	                            TscatterPingPongProcessChunk<ParallelGroupType, GlobalSrcData, TileData>(
352	                                parallelGroup, srcGlobalData, pingTile, pongTile, srcOff, dstOff, curRows, curCols,
353	                                srcChunkStride, dstChunkStride, r, state);
354	                        }
355	                    }
356	                }
357	            }
358	        }
359	    }
360	
361	    TscatterPingPongEpilogue<ParallelGroupType, TileData>(parallelGroup, pingTile, pongTile, state, dstChunkStride);
362	}
