364	// ============================================================================
365	// TSCATTER_IMPL (ping-pong): Scatter with double buffering
366	//
367	// Uses two staging tiles (pingTile, pongTile) to overlap TLOAD of the next
368	// chunk (MTE2) with TSTORE of the current chunk (MTE3).
369	//
370	// Timeline without ping-pong:
371	//   [TLOAD chunk0] -> [TSTORE chunk0] -> [TLOAD chunk1] -> [TSTORE chunk1] -> ...
372	//
373	// Timeline with ping-pong:
374	//   [TLOAD chunk0] -> [TSTORE chunk0 | TLOAD chunk1] -> [TSTORE chunk1 | TLOAD chunk2] -> ...
375	//
376	// Constraints: same as TSCATTER_IMPL for chunked mode.
377	// ============================================================================
378	
379	template <typename ParallelGroupType, typename GlobalSrcData, typename TileData>
380	PTO_INTERNAL void TSCATTER_IMPL(
381	    ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile)
382	{
383	    using DstGlobalT = typename ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
384	    using ElemT = typename GlobalSrcData::RawDType;
385	
386	    static_assert(std::is_same_v<ElemT, typename DstGlobalT::RawDType>, "TSCATTER: GlobalData type mismatch!");
387	    static_assert(
388	        std::is_same_v<ElemT, typename TileData::DType>,
389	        "TSCATTER: TileData element type must match GlobalData element type");
390	    static_assert(GlobalSrcData::layout == DstGlobalT::layout, "TSCATTER: src/dst layout mismatch");
391	
392	    const int nranks = parallelGroup.GetSize();
393	    const int rootIdx = parallelGroup.GetRootIdx();
394	
395	    PTO_ASSERT(nranks > 0, "TSCATTER: ParallelGroup size must be positive");
396	    PTO_ASSERT(rootIdx >= 0 && rootIdx < nranks, "TSCATTER: rootIdx out of range");
397	
398	    auto& dstRef = parallelGroup[0];
399	    const int dims[5] = {
400	        static_cast<int>(dstRef.GetShape(GlobalTensorDim::DIM_0)),
401	        static_cast<int>(dstRef.GetShape(GlobalTensorDim::DIM_1)),
402	        static_cast<int>(dstRef.GetShape(GlobalTensorDim::DIM_2)),
403	        static_cast<int>(dstRef.GetShape(GlobalTensorDim::DIM_3)),
404	        static_cast<int>(dstRef.GetShape(GlobalTensorDim::DIM_4))};
405	
406	    const int perRankRows = dims[3];
407	    const int tileValidRow = pingTile.GetValidRow();
408	    const int tileValidCol = pingTile.GetValidCol();
409	    const int64_t totalRows = static_cast<int64_t>(dims[0]) * dims[1] * dims[2] * dims[3];
410	
411	    PTO_ASSERT(tileValidRow > 0, "TSCATTER: tileValidRow must be greater than 0");
412	    PTO_ASSERT(tileValidCol > 0, "TSCATTER: tileValidCol must be greater than 0");
413	
414	    if (totalRows == 0 || dims[4] == 0) {
415	        return;
416	    }
417	
418	    // Simple path: per-rank data fits in UB tile, no ping-pong benefit
419	    if (totalRows <= tileValidRow && dims[4] <= tileValidCol) {
420	        TscatterSimple<ParallelGroupType, GlobalSrcData, TileData>(
421	            parallelGroup, srcGlobalData, pingTile, dims[0], dims[1], dims[2], dims[3], dims[4], nranks, perRankRows);
422	        return;
423	    }
424	
425	    // 2D sliding chunked path with ping-pong double buffering
426	    constexpr bool hasDynRow = (TileData::ValidRow == DYNAMIC);
427	    constexpr bool hasDynCol = (TileData::ValidCol == DYNAMIC);
428	
429	    if constexpr (!hasDynRow) {
430	        PTO_ASSERT(
431	            dims[3] % tileValidRow == 0,
432	            "TSCATTER chunked: per-rank DIM_3 must be divisible by tile ValidRow when static.");
433	    }
434	    if constexpr (!hasDynCol) {
435	        PTO_ASSERT(
436	            dims[4] % tileValidCol == 0, "TSCATTER chunked: DIM_4 must be divisible by tile ValidCol when static.");
437	    }
438	
439	    TscatterChunkedPingPong<ParallelGroupType, GlobalSrcData, TileData>(
440	        parallelGroup, srcGlobalData, pingTile, pongTile, dims[0], dims[1], dims[2], dims[3], dims[4], tileValidRow,
441	        tileValidCol, nranks, perRankRows);
442	}
443	
444	// CCU engine is only available on A5 hardware.  Stub mirrors the URMA branch
445	// in `a2a3/async/TPutAsync.hpp`: the template name must exist for the
446	// qualified template-id `::pto::comm::TSCATTER_CCU_IMPL<engine>(...)` in
447	// pto_comm_inst.hpp to parse on A2/A3; the static_assert is dependent on the
448	// `engine` parameter and only fires if the overload is actually instantiated.
449	// `a5/TScatter.hpp` defines `PTO_COMM_A5_TSCATTER_PROVIDED` before including
450	// this header so the stub is omitted on A5 builds, where the real
451	// `TSCATTER_CCU_IMPL` overload lives.  Otherwise the generic `Args&&...` pack
452	// would compete with the real `T&` parameters in `pto::comm`'s overload set
453	// and could win under partial ordering on some compilers.
454	#ifndef PTO_COMM_A5_TSCATTER_PROVIDED
455	template <CollEngine engine = CollEngine::CCU, typename... Args>
456	PTO_INTERNAL void TSCATTER_CCU_IMPL(Args&&...)
457	{
458	    static_assert(
459	        engine != CollEngine::CCU, "TSCATTER<CollEngine::CCU> requires A5 hardware; "
460	                                   "CCU engine is not available on A2/A3.");
461	}
462	#endif // PTO_COMM_A5_TSCATTER_PROVIDED
463	
464	} // namespace comm
465	} // namespace pto
466	
467	#endif // PTO_COMM_TSCATTER_HPP
