504	template <
505	    typename Tsrc0, typename Tsrc1, int kGRows0_, int kGCols0_, int kGRows1_, int kGCols1_, int kTRows_, int kTCols_>
506	inline AICORE void runTGather1D(__gm__ Tsrc0 __out__* out, __gm__ Tsrc0 __in__* src0, __gm__ Tsrc1 __in__* src1)
507	{
508	    using DynShapeDim5_src0 = pto::Shape<1, 1, 1, kGRows0_, kGCols0_>;
509	    using DynStridDim5_src0 = pto::Stride<1, 1, 1, kGCols0_, 1>;
510	    using GlobalData_src0 = GlobalTensor<Tsrc0, DynShapeDim5_src0, DynStridDim5_src0>;
511	    using DynShapeDim5_src1 = pto::Shape<1, 1, 1, kGRows1_, kGCols1_>;
512	    using DynStridDim5_src1 = pto::Stride<1, 1, 1, kGCols1_, 1>;
513	    using GlobalData_src1 = GlobalTensor<Tsrc1, DynShapeDim5_src1, DynStridDim5_src1>;
514	    using DynShapeDim5_dst = pto::Shape<1, 1, 1, kGRows1_, kGCols1_>;
515	    using DynStridDim5_dst = pto::Stride<1, 1, 1, kGCols1_, 1>;
516	    using GlobalData_dst = GlobalTensor<Tsrc0, DynShapeDim5_dst, DynStridDim5_dst>;
517	
518	    constexpr int src0_row = kGRows0_;
519	    constexpr int src0_col = kGCols0_;
520	    constexpr int src1_row = kGRows1_;
521	    constexpr int src1_col = kGCols1_;
522	    constexpr int dst_row = kGRows1_;
523	    constexpr int dst_col = kGCols1_;
524	
525	    using TileData_src0 = Tile<TileType::Vec, Tsrc0, kGRows0_, kGCols0_, BLayout::RowMajor, -1, -1>;
526	    using TileData_src1 = Tile<TileType::Vec, Tsrc1, kGRows1_, kGCols1_, BLayout::RowMajor, -1, -1>;
527	    using TileData_dst = Tile<TileType::Vec, Tsrc0, kGRows1_, kGCols1_, BLayout::RowMajor, -1, -1>;
528	    using TileData_tmp = Tile<TileType::Vec, Tsrc1, kGRows1_, kGCols1_, BLayout::RowMajor, -1, -1>;
529	    TileData_src0 src0Tile(src0_row, src0_col);
530	    TileData_src1 src1Tile(src1_row, src1_col);
531	    TileData_dst dstTile(dst_row, dst_col);
532	    TileData_tmp tmpTile(src1_row, src1_col);
533	
534	    TASSIGN(src0Tile, 0x0);
535	    TASSIGN(src1Tile, 0x0 + src0_row * src0_col * sizeof(Tsrc0));
536	    TASSIGN(dstTile, 0x0 + src0_row * src0_col * sizeof(Tsrc0) + src1_row * src1_col * sizeof(Tsrc1));
