24	// Tests the TREDUCE collective - root gathers and reduces data from all ranks
25	// ============================================================================
26	template <typename T, size_t total_rows, size_t cols, size_t tile_rows>
27	__global__ AICORE void TReduceKernelImpl(
28	    __gm__ T* src0, __gm__ T* src1, __gm__ T* output, int nranks, pto::comm::ReduceOp op)
29	{
30	    constexpr size_t total_count = total_rows * cols;
31	
32	    using ShapeDyn = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
33	    using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
34	    using Global = pto::GlobalTensor<T, ShapeDyn, StrideDyn, pto::Layout::ND>;
35	    using TileData = pto::Tile<pto::TileType::Vec, T, tile_rows, cols, pto::BLayout::RowMajor, -1, -1>;
36	
37	    int my_rank = 0;
38	
39	    // Full shape for the large GlobalTensor
40	    ShapeDyn fullShape(1, 1, 1, total_rows, cols);
41	    StrideDyn fullStride(total_count, total_count, total_count, cols, 1);
42	
43	    Global outputG(output, fullShape, fullStride);
44	
45	    // Create ParallelGroup: each tensor points to that rank's input buffer
46	    Global tensors[2];
47	    int actual_nranks = 2;
48	    tensors[0] = Global(src0, fullShape, fullStride);
49	    tensors[1] = Global(src1, fullShape, fullStride);
50	
51	    ParallelGroup<Global> pg(tensors, actual_nranks, my_rank);
52	
53	    // Allocate UB tiles — TREDUCE_IMPL will auto-chunk using these
54	    TileData accTile(tile_rows, cols);
55	    TileData recvTile(tile_rows, cols);
56	
57	    TASSIGN(accTile, 0x0);
58	    TASSIGN(recvTile, 0x10000);
59	
60	    // Only root executes TREDUCE
61	    if (my_rank == 0) {
62	        TREDUCE(pg, outputG, accTile, recvTile, op);
63	    }
64	}
65	
66	template <typename T, int kGRows_, int kGCols_, int kTRows_, int kTCols_>
67	void LaunchTReduce(T* src0, T* src1, T* dst, pto::comm::ReduceOp op, void* stream)
68	{
69	    TReduceKernelImpl<T, kGRows_, kGCols_, kTRows_>(src0, src1, dst, 2, op);
70	}
71	
72	template void LaunchTReduce<int32_t, 64, 64, 64, 64>(
73	    int32_t* src0, int32_t* src1, int32_t* dst, pto::comm::ReduceOp op, void* stream);
