10	
11	#ifndef PTO_TREDUCE_HPP
12	#define PTO_TREDUCE_HPP
13	
14	#include <type_traits>
15	
16	#include "pto/common/debug.h"
17	#include "pto/common/type.hpp"
18	#include "pto/common/constants.hpp"
19	#include "pto/common/pto_instr.hpp"
20	#include "pto/comm/comm_types.hpp"
21	
22	namespace pto {
23	namespace comm {
24	
25	// ============================================================================
26	// TREDUCE_IMPL: Reduce operation - root gathers and reduces data from all ranks
27	//
28	// The calling NPU is the root and gathers data from all ranks, performing
29	// element-wise reduction locally.
30	//
31	// When the GlobalTensor exceeds the UB tile capacity in rows and/or columns,
32	// the transfer is automatically chunked via 2D sliding:
33	//   - Outer dimensions (DIM_0, DIM_1, DIM_2) are iterated explicitly.
34	//   - DIM_3 (rows) is split into tileValidRow-sized chunks.
35	//   - DIM_4 (cols) is split into tileValidCol-sized chunks.
36	//
37	// For each chunk, the full reduce pipeline is executed:
38	//   1. Load root's chunk into accTileData
39	//   2. For each remote rank: TLOAD chunk into recvTileData, reduce into acc
40	//   3. Store reduced chunk to dstGlobalData
41	//
42	// Constraints for chunked mode:
43	//   - If TileData has static ValidRow, shape3 must be divisible by ValidRow.
44	//     Use DYNAMIC ValidRow for partial row chunk support.
45	//   - If TileData has static ValidCol, shape4 must be divisible by ValidCol.
46	//     Use DYNAMIC ValidCol for partial column chunk support.
47	//   - All ranks in the ParallelGroup are assumed to have the same shape/strides.
48	// ============================================================================
49	
50	namespace detail {
51	
52	// Element-wise reduction helper
53	template <typename TileData>
54	PTO_INTERNAL void ReduceTiles(TileData& acc, TileData& recv, pto::comm::ReduceOp op)
55	{
56	    // Perform element-wise reduction based on op
57	    switch (op) {
58	        case pto::comm::ReduceOp::Sum:
59	            TADD(acc, acc, recv);
60	            break;
61	        case pto::comm::ReduceOp::Max:
62	            TMAX(acc, acc, recv);
63	            break;
64	        case pto::comm::ReduceOp::Min:
65	            TMIN(acc, acc, recv);
66	            break;
67	        default:
68	            PTO_ASSERT(false, "TREDUCE: unknown ReduceOp");
69	            break;
70	    }
71	}
72	
73	PTO_INTERNAL int GetRemoteRank(int rootIdx, int remoteOrdinal)
74	{
75	    return (remoteOrdinal < rootIdx) ? remoteOrdinal : (remoteOrdinal + 1);
76	}
77	
78	} // namespace detail
79	
80	template <typename ParallelGroupType, typename GlobalDstData, typename TileData>
81	PTO_INTERNAL void TREDUCE_IMPL(
82	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& accTileData, TileData& recvTileData,
83	    pto::comm::ReduceOp op)
84	{
85	    using GlobalSrcData = typename pto::comm::ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
86	    using T = typename GlobalSrcData::RawDType;
87	
88	    // Type checks
89	    static_assert(std::is_same_v<T, typename GlobalDstData::RawDType>, "TREDUCE: GlobalData type mismatch!");
90	    static_assert(
91	        std::is_same_v<T, typename TileData::DType>,
92	        "TREDUCE: TileData element type must match GlobalData element type");
93	
94	    const int rootIdx = parallelGroup.GetRootIdx();
95	    const int nranks = parallelGroup.GetSize();
96	
97	    // Check PG size
98	    PTO_ASSERT(nranks > 0, "ParallelGroup size must be greater than 0!");
99	    PTO_ASSERT(rootIdx >= 0 && rootIdx < nranks, "rootIdx must be in range [0, nranks)!");
100	
101	    // Get GlobalTensor dimensions from root's source tensor
102	    GlobalSrcData& refTensor = parallelGroup[rootIdx];
103	    const int gShape0 = refTensor.GetShape(GlobalTensorDim::DIM_0);
104	    const int gShape1 = refTensor.GetShape(GlobalTensorDim::DIM_1);
105	    const int gShape2 = refTensor.GetShape(GlobalTensorDim::DIM_2);
106	    const int gShape3 = refTensor.GetShape(GlobalTensorDim::DIM_3);
107	    const int gShape4 = refTensor.GetShape(GlobalTensorDim::DIM_4);
108	
109	    const int64_t totalRows = static_cast<int64_t>(gShape0) * gShape1 * gShape2 * gShape3;
110	    const int tileValidRow = accTileData.GetValidRow();
111	    const int tileValidCol = accTileData.GetValidCol();
112	
113	    PTO_ASSERT(tileValidRow > 0, "TREDUCE: tileValidRow must be greater than 0");
114	    PTO_ASSERT(tileValidCol > 0, "TREDUCE: tileValidCol must be greater than 0");
115	
116	    if (totalRows == 0 || gShape4 == 0) {
117	        return;
118	    }
119	
120	    // ---- Simple path: data fits in UB tile in both dimensions ----
121	    if (totalRows <= tileValidRow && gShape4 <= tileValidCol) {
122	        // Single rank case: just copy local data to output
123	        if (nranks == 1) {
124	            TLOAD(accTileData, parallelGroup[rootIdx]);
125	            TSTORE(dstGlobalData, accTileData);
126	            return;
127	        }
128	
129	        // Step 1: Load root data into accumulator
130	        TLOAD(accTileData, parallelGroup[rootIdx]);
131	
132	        // Step 2: Reduce data from all other ranks
133	        for (int r = 0; r < nranks; ++r) {
134	            if (r == rootIdx) {
135	                continue; // Skip self, already loaded
136	            }
137	
138	            // Load remote data into receive buffer
139	            TLOAD(recvTileData, parallelGroup[r]);
140	
141	            // Perform reduction
142	            detail::ReduceTiles(accTileData, recvTileData, op);
143	        }
144	        TSTORE(dstGlobalData, accTileData);
145	        return;
146	    }
147	
148	    // ---- 2D sliding chunked path ----
149	    //
150	    // Strategy (ND layout):
151	    //   - Iterate over outer dimensions (dim0, dim1, dim2) explicitly.
152	    //   - Within each (i0, i1, i2) block, slide a (tileValidRow x tileValidCol)
153	    //     window over the (dim3 x dim4) plane.
154	    //   - For each chunk, execute the full reduce pipeline:
155	    //     TLOAD root chunk → reduce all remote chunks → TSTORE result.
156	
157	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
158	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
159	
160	    // Row validation: static ValidRow requires shape3 to be exactly divisible
161	    if constexpr (!isDynamicRow) {
162	        PTO_ASSERT(
163	            gShape3 % tileValidRow == 0,
164	            "TREDUCE chunked: shape3 must be divisible by tile ValidRow when ValidRow is static. "
165	            "Use a Tile with DYNAMIC ValidRow for partial row chunk support.");
166	    }
167	    // Column validation: static ValidCol requires shape4 to be exactly divisible
168	    if constexpr (!isDynamicCol) {
169	        PTO_ASSERT(
170	            gShape4 % tileValidCol == 0,
171	            "TREDUCE chunked: shape4 must be divisible by tile ValidCol when ValidCol is static. "
172	            "Use a Tile with DYNAMIC ValidCol for partial column chunk support.");
173	    }
174	
175	    // Source strides (from root's tensor, assumed same for all ranks)
176	    const int srcStride0 = refTensor.GetStride(GlobalTensorDim::DIM_0);
177	    const int srcStride1 = refTensor.GetStride(GlobalTensorDim::DIM_1);
178	    const int srcStride2 = refTensor.GetStride(GlobalTensorDim::DIM_2);
179	    const int srcStride3 = refTensor.GetStride(GlobalTensorDim::DIM_3);
180	    const int srcStride4 = refTensor.GetStride(GlobalTensorDim::DIM_4);
181	
182	    // Destination strides
183	    const int dstStride0 = dstGlobalData.GetStride(GlobalTensorDim::DIM_0);
184	    const int dstStride1 = dstGlobalData.GetStride(GlobalTensorDim::DIM_1);
185	    const int dstStride2 = dstGlobalData.GetStride(GlobalTensorDim::DIM_2);
186	    const int dstStride3 = dstGlobalData.GetStride(GlobalTensorDim::DIM_3);
187	    const int dstStride4 = dstGlobalData.GetStride(GlobalTensorDim::DIM_4);
188	
189	    // View types with fully dynamic shape/stride for chunk GlobalTensors
190	    using DynShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
191	    using DynStride = Stride<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
192	    using SrcViewT = GlobalTensor<T, DynShape, DynStride, GlobalSrcData::layout>;
193	    using DstViewT = GlobalTensor<T, DynShape, DynStride, GlobalDstData::layout>;
194	    DynStride srcChunkStride(srcStride0, srcStride1, srcStride2, srcStride3, srcStride4);
195	    DynStride dstChunkStride(dstStride0, dstStride1, dstStride2, dstStride3, dstStride4);
196	
197	    // 2D sliding: iterate outer dims, then chunk rows (dim3) and columns (dim4)
198	    for (int i0 = 0; i0 < gShape0; ++i0) {
199	        for (int i1 = 0; i1 < gShape1; ++i1) {
200	            for (int i2 = 0; i2 < gShape2; ++i2) {
201	                int64_t srcBase = static_cast<int64_t>(i0) * srcStride0 + static_cast<int64_t>(i1) * srcStride1 +
202	                                  static_cast<int64_t>(i2) * srcStride2;
203	                int64_t dstBase = static_cast<int64_t>(i0) * dstStride0 + static_cast<int64_t>(i1) * dstStride1 +
204	                                  static_cast<int64_t>(i2) * dstStride2;
205	
206	                for (int rowOff = 0; rowOff < gShape3; rowOff += tileValidRow) {
207	                    int currentRows = (rowOff + tileValidRow <= gShape3) ? tileValidRow : (gShape3 - rowOff);
208	
209	                    if constexpr (isDynamicRow) {
210	                        accTileData.RowMaskInternal = currentRows;
211	                        recvTileData.RowMaskInternal = currentRows;
212	                    }
213	
214	                    for (int colOff = 0; colOff < gShape4; colOff += tileValidCol) {
215	                        int currentCols = (colOff + tileValidCol <= gShape4) ? tileValidCol : (gShape4 - colOff);
216	
217	                        if constexpr (isDynamicCol) {
218	                            accTileData.ColMaskInternal = currentCols;
219	                            recvTileData.ColMaskInternal = currentCols;
220	                        }
221	
222	                        // Compute element offsets for this chunk
223	                        int64_t srcOffset = srcBase + static_cast<int64_t>(rowOff) * srcStride3 +
224	                                            static_cast<int64_t>(colOff) * srcStride4;
225	                        int64_t dstOffset = dstBase + static_cast<int64_t>(rowOff) * dstStride3 +
226	                                            static_cast<int64_t>(colOff) * dstStride4;
227	
228	                        DynShape chunkShape(1, 1, 1, currentRows, currentCols);
229	
230	                        // Load root's chunk into accumulator
231	                        SrcViewT rootView(parallelGroup[rootIdx].data() + srcOffset, chunkShape, srcChunkStride);
232	                        TLOAD(accTileData, rootView);
233	
234	                        if (nranks != 1) {
235	                            for (int r = 0; r < nranks; ++r) {
236	                                if (r == rootIdx)
237	                                    continue;
238	
239	                                SrcViewT remoteView(parallelGroup[r].data() + srcOffset, chunkShape, srcChunkStride);
240	                                TLOAD(recvTileData, remoteView);
241	
242	                                detail::ReduceTiles(accTileData, recvTileData, op);
243	                            }
244	                        }
245	
246	                        // Store reduced chunk to destination
247	                        DstViewT dstView(dstGlobalData.data() + dstOffset, chunkShape, dstChunkStride);
248	                        TSTORE(dstView, accTileData);
249	                    }
250	                }
251	            }
252	        }
253	    }
254	}
255	
256	// ============================================================================
257	// TREDUCE_IMPL (ping-pong): Reduce operation with double buffering
258	//
259	// The calling NPU is the root and gathers data from all ranks, performing
260	// element-wise reduction locally. Uses ping-pong double buffering to overlap
261	// remote data transfer (TLOAD) with reduction computation.
262	//
263	// When the GlobalTensor exceeds the UB tile capacity, the operation is
264	// automatically chunked via 2D sliding (same as TREDUCE_IMPL). Within each
265	// chunk, ping-pong double buffering is applied to the remote rank reduction:
266	//
267	// Timeline without ping-pong:
268	//   [TLOAD remote0] -> [Reduce] -> [TLOAD remote1] -> [Reduce] -> ...
269	//
270	// Timeline with ping-pong (overlap TLOAD[i+1] with Reduce[i]):
271	//   [TLOAD remote0] -> [Reduce remote0 | TLOAD remote1] -> [Reduce remote1 | TLOAD remote2] -> ...
272	//
273	// Constraints: same as TREDUCE_IMPL for chunked mode.
274	// ============================================================================
275	template <typename ParallelGroupType, typename GlobalDstData, typename TileData>
276	PTO_INTERNAL void TREDUCE_IMPL(
277	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& accTileData, TileData& pingTile,
278	    TileData& pongTile, pto::comm::ReduceOp op)
279	{
280	    using GlobalSrcData = typename pto::comm::ParallelGroupTraits<ParallelGroupType>::GlobalDataType;
281	    using T = typename GlobalSrcData::RawDType;
282	
283	    // Type checks
284	    static_assert(std::is_same_v<T, typename GlobalDstData::RawDType>, "TREDUCE: GlobalData type mismatch!");
285	    static_assert(
286	        std::is_same_v<T, typename TileData::DType>,
287	        "TREDUCE: TileData element type must match GlobalData element type");
288	
289	    const int rootIdx = parallelGroup.GetRootIdx();
290	    const int nranks = parallelGroup.GetSize();
291	
292	    // Check PG size
293	    PTO_ASSERT(nranks > 0, "ParallelGroup size must be greater than 0!");
294	    PTO_ASSERT(rootIdx >= 0 && rootIdx < nranks, "rootIdx must be in range [0, nranks)!");
295	
296	    // Get GlobalTensor dimensions from root's source tensor
297	    GlobalSrcData& refTensor = parallelGroup[rootIdx];
298	    const int gShape0 = refTensor.GetShape(GlobalTensorDim::DIM_0);
299	    const int gShape1 = refTensor.GetShape(GlobalTensorDim::DIM_1);
300	    const int gShape2 = refTensor.GetShape(GlobalTensorDim::DIM_2);
301	    const int gShape3 = refTensor.GetShape(GlobalTensorDim::DIM_3);
302	    const int gShape4 = refTensor.GetShape(GlobalTensorDim::DIM_4);
303	
304	    const int64_t totalRows = static_cast<int64_t>(gShape0) * gShape1 * gShape2 * gShape3;
305	    const int tileValidRow = accTileData.GetValidRow();
306	    const int tileValidCol = accTileData.GetValidCol();
307	
308	    PTO_ASSERT(tileValidRow > 0, "TREDUCE: tileValidRow must be greater than 0");
309	    PTO_ASSERT(tileValidCol > 0, "TREDUCE: tileValidCol must be greater than 0");
310	
311	    if (totalRows == 0 || gShape4 == 0) {
312	        return;
313	    }
314	
315	    // Remote ranks are all ranks except root; map by ordinal to concrete rank index.
316	    const int numRemote = nranks - 1;
317	
318	    // ---- Simple path: data fits in UB tile in both dimensions ----
319	    if (totalRows <= tileValidRow && gShape4 <= tileValidCol) {
320	        // Single rank case: just copy local data to output
321	        if (nranks == 1) {
322	            TLOAD(accTileData, parallelGroup[rootIdx]);
323	            TSTORE(dstGlobalData, accTileData);
324	            return;
325	        }
326	
327	        // Step 1: Load root data into accumulator
328	        TLOAD(accTileData, parallelGroup[rootIdx]);
329	
330	        // Step 2: Start prefetching first remote data into pingTile
331	        TLOAD(pingTile, parallelGroup[detail::GetRemoteRank(rootIdx, 0)]);
332	
333	        // Ping-pong processing: overlap data transfer with computation
334	        for (int i = 0; i < numRemote; ++i) {
335	            const bool hasNext = (i + 1 < numRemote);
336	            const bool usePing = (i % 2 == 0);
337	
338	            TileData& currentTile = usePing ? pingTile : pongTile;
339	            TileData& nextTile = usePing ? pongTile : pingTile;
340	
341	            // Start prefetch of next remote data (overlapped with current reduction)
342	            if (hasNext) {
343	                TLOAD(nextTile, parallelGroup[detail::GetRemoteRank(rootIdx, i + 1)]);
344	            }
345	
346	            // Perform reduction with current remote data
347	            detail::ReduceTiles(accTileData, currentTile, op);
348	        }
349	
350	        // Step 3: Store final result
351	        TSTORE(dstGlobalData, accTileData);
352	        return;
353	    }
354	
355	    // ---- 2D sliding chunked path ----
356	    //
357	    // Strategy: same 2D sliding as TREDUCE_IMPL, but within each chunk the
358	    // remote-rank reduction uses ping-pong double buffering.
359	
360	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
361	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
362	
363	    if constexpr (!isDynamicRow) {
364	        PTO_ASSERT(
365	            gShape3 % tileValidRow == 0,
366	            "TREDUCE chunked: shape3 must be divisible by tile ValidRow when ValidRow is static. "
367	            "Use a Tile with DYNAMIC ValidRow for partial row chunk support.");
368	    }
369	    if constexpr (!isDynamicCol) {
370	        PTO_ASSERT(
371	            gShape4 % tileValidCol == 0,
372	            "TREDUCE chunked: shape4 must be divisible by tile ValidCol when ValidCol is static. "
373	            "Use a Tile with DYNAMIC ValidCol for partial column chunk support.");
374	    }
375	
376	    // Source strides (from root's tensor, assumed same for all ranks)
377	    const int srcStride0 = refTensor.GetStride(GlobalTensorDim::DIM_0);
378	    const int srcStride1 = refTensor.GetStride(GlobalTensorDim::DIM_1);
379	    const int srcStride2 = refTensor.GetStride(GlobalTensorDim::DIM_2);
380	    const int srcStride3 = refTensor.GetStride(GlobalTensorDim::DIM_3);
381	    const int srcStride4 = refTensor.GetStride(GlobalTensorDim::DIM_4);
382	
383	    // Destination strides
384	    const int dstStride0 = dstGlobalData.GetStride(GlobalTensorDim::DIM_0);
385	    const int dstStride1 = dstGlobalData.GetStride(GlobalTensorDim::DIM_1);
386	    const int dstStride2 = dstGlobalData.GetStride(GlobalTensorDim::DIM_2);
387	    const int dstStride3 = dstGlobalData.GetStride(GlobalTensorDim::DIM_3);
388	    const int dstStride4 = dstGlobalData.GetStride(GlobalTensorDim::DIM_4);
389	
390	    // View types with fully dynamic shape/stride for chunk GlobalTensors
391	    using DynShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
392	    using DynStride = Stride<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
393	    using SrcViewT = GlobalTensor<T, DynShape, DynStride, GlobalSrcData::layout>;
394	    using DstViewT = GlobalTensor<T, DynShape, DynStride, GlobalDstData::layout>;
395	    DynStride srcChunkStride(srcStride0, srcStride1, srcStride2, srcStride3, srcStride4);
396	    DynStride dstChunkStride(dstStride0, dstStride1, dstStride2, dstStride3, dstStride4);
397	
398	    // 2D sliding: iterate outer dims, then chunk rows (dim3) and columns (dim4)
399	    for (int i0 = 0; i0 < gShape0; ++i0) {
400	        for (int i1 = 0; i1 < gShape1; ++i1) {
401	            for (int i2 = 0; i2 < gShape2; ++i2) {
402	                int64_t srcBase = static_cast<int64_t>(i0) * srcStride0 + static_cast<int64_t>(i1) * srcStride1 +
403	                                  static_cast<int64_t>(i2) * srcStride2;
404	                int64_t dstBase = static_cast<int64_t>(i0) * dstStride0 + static_cast<int64_t>(i1) * dstStride1 +
405	                                  static_cast<int64_t>(i2) * dstStride2;
406	
407	                for (int rowOff = 0; rowOff < gShape3; rowOff += tileValidRow) {
408	                    int currentRows = (rowOff + tileValidRow <= gShape3) ? tileValidRow : (gShape3 - rowOff);
409	
410	                    if constexpr (isDynamicRow) {
411	                        accTileData.RowMaskInternal = currentRows;
412	                        pingTile.RowMaskInternal = currentRows;
413	                        pongTile.RowMaskInternal = currentRows;
414	                    }
415	
416	                    for (int colOff = 0; colOff < gShape4; colOff += tileValidCol) {
417	                        int currentCols = (colOff + tileValidCol <= gShape4) ? tileValidCol : (gShape4 - colOff);
418	
419	                        if constexpr (isDynamicCol) {
420	                            accTileData.ColMaskInternal = currentCols;
421	                            pingTile.ColMaskInternal = currentCols;
422	                            pongTile.ColMaskInternal = currentCols;
423	                        }
424	
425	                        // Compute element offsets for this chunk
426	                        int64_t srcOffset = srcBase + static_cast<int64_t>(rowOff) * srcStride3 +
427	                                            static_cast<int64_t>(colOff) * srcStride4;
428	                        int64_t dstOffset = dstBase + static_cast<int64_t>(rowOff) * dstStride3 +
429	                                            static_cast<int64_t>(colOff) * dstStride4;
430	
431	                        DynShape chunkShape(1, 1, 1, currentRows, currentCols);
432	
433	                        // Load root's chunk into accumulator
434	                        SrcViewT rootView(parallelGroup[rootIdx].data() + srcOffset, chunkShape, srcChunkStride);
435	                        TLOAD(accTileData, rootView);
436	
437	                        if (nranks != 1) {
438	                            // Prefetch first remote chunk into pingTile
439	                            SrcViewT firstRemoteView(
440	                                parallelGroup[detail::GetRemoteRank(rootIdx, 0)].data() + srcOffset, chunkShape,
441	                                srcChunkStride);
442	                            TLOAD(pingTile, firstRemoteView);
443	
444	                            // Ping-pong reduce over remote ranks
445	                            for (int i = 0; i < numRemote; ++i) {
446	                                const bool hasNext = (i + 1 < numRemote);
447	                                const bool usePing = (i % 2 == 0);
448	
449	                                TileData& currentTile = usePing ? pingTile : pongTile;
450	                                TileData& nextTile = usePing ? pongTile : pingTile;
451	
452	                                // Start prefetch of next remote chunk (overlapped with reduction)
453	                                if (hasNext) {
454	                                    SrcViewT nextRemoteView(
455	                                        parallelGroup[detail::GetRemoteRank(rootIdx, i + 1)].data() + srcOffset,
456	                                        chunkShape, srcChunkStride);
457	                                    TLOAD(nextTile, nextRemoteView);
458	                                }
459	
460	                                detail::ReduceTiles(accTileData, currentTile, op);
461	                            }
462	                        }
463	
464	                        // Store reduced chunk to destination
465	                        DstViewT dstView(dstGlobalData.data() + dstOffset, chunkShape, dstChunkStride);
466	                        TSTORE(dstView, accTileData);
467	                    }
468	                }
469	            }
470	        }
471	    }
472	}
473	
474	template <
475	    CollEngine = CollEngine::CCU, typename ParallelGroupType, typename GlobalDstData, typename TileData,
476	    typename... WaitEvents>
477	PTO_INTERNAL void TREDUCE_CCU_IMPL(
478	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& accTileData, TileData& recvTileData,
479	    ReduceOp op, const CcuTriggerContext& ctx, WaitEvents&... events)
480	{
481	    TREDUCE_IMPL(parallelGroup, dstGlobalData, accTileData, recvTileData, op);
482	}
483	
484	template <
485	    CollEngine = CollEngine::CCU, typename ParallelGroupType, typename GlobalDstData, typename TileData,
486	    typename... WaitEvents>
487	PTO_INTERNAL void TREDUCE_CCU_IMPL(
488	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& accTileData, TileData& pingTileData,
489	    TileData& pongTileData, ReduceOp op, const CcuTriggerContext& ctx, WaitEvents&... events)
490	{
491	    TREDUCE_IMPL(parallelGroup, dstGlobalData, accTileData, pingTileData, pongTileData, op);
492	}
493	
494	} // namespace comm
495	} // namespace pto
496	
497	#endif
